-- Zoy0m/K1borg | 2026-09-09 | client-only visual/trade simulation.
-- Local inventory edits are NOT real items or completed server trades.
-- External assets still depend on Roblox permissions and network availability.
local Runtime = {connections = {}, cleanup = {}, alive = true, assets = setmetatable({}, {__mode = "k"})}
do
	local previous = rawget(_G, "Zoy0mK1borgRuntime")
	if type(previous) == "table" and type(previous.Destroy) == "function" then
		pcall(previous.Destroy)
	end
end
function Runtime.Connect(signal, callback)
	local connection = signal:Connect(function(...)
		if Runtime.alive then return callback(...) end
	end)
	table.insert(Runtime.connections, connection)
	return connection
end
function Runtime.Destroy()
	if not Runtime.alive then return end
	Runtime.alive = false
	for _, connection in ipairs(Runtime.connections) do pcall(function() connection:Disconnect() end) end
	for i = #Runtime.cleanup, 1, -1 do pcall(Runtime.cleanup[i]) end
	table.clear(Runtime.connections)
	table.clear(Runtime.cleanup)
end
function Runtime.Child(parent, name)
	local child = parent:FindFirstChild(name) or parent:WaitForChild(name, 20)
	assert(child, "[hashima|Dc:pipirka0258] Missing game component: " .. name .. ". Wait for MM2 to finish loading.")
	return child
end
function Runtime.Amount(value, fallback)
	local amount = tonumber(value)
	if amount == nil then amount = fallback end
	if type(amount) ~= "number" or amount ~= amount or amount == math.huge or amount == -math.huge then return nil end
	amount = math.floor(amount)
	if amount < 1 then return nil end
	return math.min(amount, 1000000)
end
_G.Zoy0mK1borgRuntime = Runtime

