local function FormatValue(v)
	if v == nil then return "?" end
	if type(v) == "number" then
		local s = tostring(math.floor(v))
		local k
		repeat s, k = string.gsub(s, "^(-?%d+)(%d%d%d)", "%1,%2") until k == 0
		return s
	end
	return tostring(v)
end

-- Restore the caller's identity even when a game module fails to load.
Runtime.modules = {}
do
	local storage = game:GetService("ReplicatedStorage")
	local previousIdentity = nil
	if type(getthreadidentity) == "function" then pcall(function() previousIdentity = getthreadidentity() end) end
	if type(setthreadidentity) == "function" then pcall(setthreadidentity, 2) end
	local ok, err = pcall(function()
		local modules = Runtime.Child(storage, "Modules")
		Runtime.modules.ProfileData = require(Runtime.Child(modules, "ProfileData"))
		Runtime.modules.InventoryModule = require(Runtime.Child(modules, "InventoryModule"))
		Runtime.modules.ItemModule = require(Runtime.Child(modules, "ItemModule"))
		Runtime.modules.Sync = require(Runtime.Child(Runtime.Child(storage, "Database"), "Sync"))
		Runtime.modules.ItemPopupService = require(Runtime.Child(Runtime.Child(storage, "ClientServices"), "ItemPopupService"))
	end)
	if type(setthreadidentity) == "function" then pcall(setthreadidentity, previousIdentity or 8) end
	if not ok then error("[Zoy0m/K1borg] Initialization failed: " .. tostring(err), 0) end
end
