local function RemoveItem(ItemName, Amount, ItemType)
	Amount = Runtime.Amount(Amount, 1)
	ItemType = ItemType or "Weapons"
	if not Amount or type(ProfileData[ItemType]) ~= "table" or type(ProfileData[ItemType].Owned) ~= "table" then return false end
	pcall(function()
		local owned = ProfileData[ItemType].Owned[ItemName]
		if not owned then
			print("doesn't have the item")
			return
		end
		if owned - Amount > 0 then
			ProfileData[ItemType].Owned[ItemName] = owned - Amount
		else
			ProfileData[ItemType].Owned[ItemName] = nil
		end
		game.ReplicatedStorage.Remotes.Inventory.InventoryDataChanged:Fire()
	end)
end

local FakeProfileOverrides = {}

local function _CloneTable(value, seen)
	if type(value) ~= "table" then return value end
	seen = seen or {}
	if seen[value] then return seen[value] end
	local copy = {}
	seen[value] = copy
	for k, v in pairs(value) do
		copy[_CloneTable(k, seen)] = _CloneTable(v, seen)
	end
	return copy
end

local function _GetFakeBucket(playerName, itemType)
	playerName = tostring(playerName or "")
	itemType = itemType or "Weapons"
	FakeProfileOverrides[playerName] = FakeProfileOverrides[playerName] or {}
	FakeProfileOverrides[playerName][itemType] = FakeProfileOverrides[playerName][itemType] or {}
	return FakeProfileOverrides[playerName][itemType]
end

local function AddFakeProfileItem(playerName, itemName, amount, itemType)
	if not playerName or playerName == "" or not itemName or itemName == "" then return end
	amount = Runtime.Amount(amount, 1)
	if not amount then return end
	local bucket = _GetFakeBucket(playerName, itemType)
	bucket[itemName] = (tonumber(bucket[itemName]) or 0) + amount
	print(("[mm2run/fake-profile] %s -> %s x%d (%s)"):format(
		tostring(playerName), tostring(itemName), amount, tostring(itemType or "Weapons")))
end

local function GetFakeProfileItems(playerName, itemType)
	local bucket = FakeProfileOverrides[tostring(playerName or "")]
	and FakeProfileOverrides[tostring(playerName or "")][itemType or "Weapons"]
	return bucket or {}
end

local function MergeFakeItemsIntoProfile(raw, playerName)
	if type(raw) ~= "table" or not playerName then return raw end
	local profile = _CloneTable(raw)

	for itemType, fakeItems in pairs(FakeProfileOverrides[tostring(playerName)] or {}) do
		if type(fakeItems) == "table" then
			profile[itemType] = type(profile[itemType]) == "table" and profile[itemType] or {}
			local owned = profile[itemType].Owned

			if type(owned) ~= "table" then
				owned = {}
				profile[itemType].Owned = owned
			end

			for itemName, amount in pairs(fakeItems) do
				local current = tonumber(owned[itemName])
				if current ~= nil then
					owned[itemName] = current + amount
				else
					local found = false
					for _, entry in pairs(owned) do
						if type(entry) == "table" then
							local entryName = entry.Name or entry.ItemName or entry.Key or entry.Id
							if entryName == itemName then
								entry.Amount = (tonumber(entry.Amount) or 0) + amount
								found = true
								break
							end
						elseif entry == itemName then
							found = true
							break
						end
					end
					if not found then
						owned[itemName] = amount
					end
				end
			end
		end
	end

	return profile
end

-- Reuse our own hook; never replace unrelated hooks during cleanup.
pcall(function()
	if type(hookmetamethod) ~= "function" or type(getnamecallmethod) ~= "function" or type(newcclosure) ~= "function" then return end
	local dispatcher = rawget(_G, "Zoy0mK1borgInventoryHook")
	if type(dispatcher) ~= "table" or not dispatcher.installed then
		dispatcher = {}
		local remote = game.ReplicatedStorage.Remotes.Extras.GetFullInventory
		local oldNamecall
		oldNamecall = hookmetamethod(game, "__namecall", newcclosure(function(self, ...)
			if self ~= remote or getnamecallmethod() ~= "InvokeServer" then return oldNamecall(self, ...) end
			local target = ...
			local raw = oldNamecall(self, ...)
			local targetName = typeof(target) == "Instance" and target:IsA("Player") and target.Name
				or (type(target) == "string" and target)
			local merge = dispatcher.merge
			if merge and targetName and type(raw) == "table" then return merge(raw, targetName) end
			return raw
		end))
		dispatcher.installed = true
		_G.Zoy0mK1borgInventoryHook = dispatcher
	end
	-- The Players calculator requests unmodified server data. Other local previews
	-- can still use the fake-profile overlay without contaminating the estimate.
	Runtime.serverReads = Runtime.serverReads or setmetatable({}, {__mode = "k"})
	local merge = function(raw, targetName)
		if Runtime.serverReads[coroutine.running()] then return raw end
		return MergeFakeItemsIntoProfile(raw, targetName)
	end
	dispatcher.merge = merge
	table.insert(Runtime.cleanup, function()
		if dispatcher.merge == merge then dispatcher.merge = nil end
	end)
end)

local function AcceptTrade()
	if not TradeTable or TradeTable.Locked then return end

	if TradeTable["Player1"]["Accepted"] == true and TradeTable["Player2"]["Accepted"] == true then
		TradeTable["Locked"] = true
		local completingTrade = TradeTable
		task.wait(0.2)
		if not Runtime.alive or TradeTable ~= completingTrade or not completingTrade.Locked then return end

		local fakePartner = nil
		if TradeTable.Player2 and TradeTable.Player2.Player then
			fakePartner = TradeTable.Player2.Player
		end

		-- Save what YOU offered as a local-only addition to the partner's profile.
		-- Keep an exact snapshot too: the "Wear fake godly" button uses this
		-- rather than guessing from every fake item accumulated in the profile.
		if fakePartner and fakePartner ~= "" and fakePartner ~= "m0_3a" then
			LastFakeTradeOffers[fakePartner] = {}
			for _, item in pairs(TradeTable["Player1"]["Offer"] or {}) do
				local itemName = item[1] or item.ItemID
				local amount = item[2] or item.Amount
				local itemType = item[3] or item.ItemType
				table.insert(LastFakeTradeOffers[fakePartner], {
					itemName = itemName,
					amount = amount,
					itemType = itemType,
				})
				AddFakeProfileItem(fakePartner, itemName, amount, itemType)
			end
		end

		if TradeTable["Player1"]["Offer"] and next(TradeTable["Player1"]["Offer"]) ~= nil then
			for _, item in pairs(TradeTable["Player1"]["Offer"]) do
				local itemName = item[1]
				local amount = item[2]
				local itemType = item[3]
				pcall(function()
					RemoveItem(itemName, amount, itemType)
				end)
			end
		end

		if TradeTable["Player2"]["Offer"] and next(TradeTable["Player2"]["Offer"]) ~= nil then
			for _, item in pairs(TradeTable["Player2"]["Offer"]) do
				local itemName = item[1]
				local amount = item[2]
				local itemType = item[3]
				pcall(function()
					GiveItem(itemName, amount, itemType)
				end)
				pcall(function()
					_G.NewItem(itemName, "You Got...", nil, itemType, amount)
				end)
			end
		end

		pcall(function()
			TradeGUI.Enabled = false
		end)

		local partner = "m0_3a"
		if TradeTable.Player2 and TradeTable.Player2.Player then
			partner = TradeTable.Player2.Player
		end

		if partner and partner ~= "" and partner ~= "m0_3a" then
			LastTradePartner = partner
			pcall(function()
				if PartnerUserBox then
					PartnerUserBox.Text = partner
				end
			end)
		end

		TradeTable = {
			["LastOffer"] = os.time(),
			["Locked"] = false,
			["Player1"] = {
				["Player"] = game.Players.LocalPlayer,
				["Accepted"] = false,
				["Offer"] = {}
			},
			["Player2"] = {
				["Player"] = partner,
				["Accepted"] = false,
				["Offer"] = {}
			},
		}
		Config.in_trade = false
	end
end

local v84 = false

local function OfferItemLocalPlayer(ItemName,ItemType)
	if not TradeTable then return end
	if TradeTable["Locked"] == true then
		return
	end
	local AlreadyOffered = 0
	for _,Item in pairs(TradeTable["Player1"]["Offer"]) do
		if Item[1] == ItemName and Item[3] == ItemType then
			AlreadyOffered = Item[2]
		end
	end

	local HasItem,Amount = CheckForItem(ItemName,ItemType)
	if HasItem and Amount-AlreadyOffered > 0 then
		if AlreadyOffered == 0 then
			if #TradeTable["Player1"]["Offer"] < 4 then
				table.insert(TradeTable["Player1"]["Offer"], {ItemName,1,ItemType})
			end
		else
			for Index,Item in pairs(TradeTable["Player1"]["Offer"]) do
				if Item[1] == ItemName and Item[3] == ItemType then
					TradeTable["Player1"]["Offer"][Index][2] = TradeTable["Player1"]["Offer"][Index][2] + 1
					break
				end
			end
		end
	end

	TradeTable["LastOffer"] = os.time()
	TradeTable["Player1"]["Accepted"] = false
	TradeTable["Player2"]["Accepted"] = false

	pcall(function()
		functions.UpdateTrade()
	end)
end

local function RemoveItemLocalPlayer(ItemName, ItemType)
	if not TradeTable then return end
	if TradeTable["Locked"] == true then
		return
	end

	if TradeTable["Player1"]["Accepted"] then
		return
	end
	TradeTable["LastOffer"] = os.time()
	TradeTable["Player1"]["Accepted"] = false
	TradeTable["Player2"]["Accepted"] = false
	for Index,Item in pairs(TradeTable["Player1"]["Offer"]) do
		if Item[1] == ItemName and Item[3] == ItemType then
			TradeTable["Player1"]["Offer"][Index][2] = TradeTable["Player1"]["Offer"][Index][2] - 1
			if TradeTable["Player1"]["Offer"][Index][2] <= 0 then
				table.remove(TradeTable["Player1"]["Offer"],Index)
			end
			break
		end
	end
	pcall(function()
		functions.UpdateTrade()
	end)
end

