-- Layered UI-only glow; no global BloomEffect, external texture, or per-frame loop.
Runtime.neon = {layers = {}, tabs = {}}
function Runtime.AddNeonLayer(target, parent, thickness, transparency, radius)
	local frame = Instance.new("Frame")
	frame.Name = "NeonGlow"
	frame.BackgroundTransparency = 1
	frame.BorderSizePixel = 0
	frame.Active = false
	frame.ZIndex = target.ZIndex
	frame.Parent = parent
	local corner = Instance.new("UICorner")
	corner.CornerRadius = UDim.new(0, radius)
	corner.Parent = frame
	local stroke = Instance.new("UIStroke")
	stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
	stroke.Color = Color3.fromRGB(0, 155, 255)
	stroke.Thickness = thickness
	stroke.Transparency = transparency
	stroke.Parent = frame
	return frame
end
do
	for _, layer in ipairs({{24, 0.97}, {18, 0.95}, {12, 0.92}, {8, 0.86}, {4, 0.67}}) do
		table.insert(Runtime.neon.layers, Runtime.AddNeonLayer(mainFrame, controlGui, layer[1], layer[2], 8))
	end
	local function syncNeon()
		for _, frame in ipairs(Runtime.neon.layers) do
			frame.Size = mainFrame.Size
			frame.Position = mainFrame.Position
			frame.AnchorPoint = mainFrame.AnchorPoint
			frame.Visible = mainFrame.Visible
		end
	end
	syncNeon()
	Runtime.Connect(mainFrame:GetPropertyChangedSignal("Size"), syncNeon)
	Runtime.Connect(mainFrame:GetPropertyChangedSignal("Position"), syncNeon)
	Runtime.Connect(mainFrame:GetPropertyChangedSignal("Visible"), syncNeon)
	mainStroke.Color = Color3.fromRGB(115, 225, 255)
	mainStroke.Thickness = 1.5
	mainStroke.Transparency = 0
end


