	heading.TextSize = 12
	heading.TextColor3 = Color3.fromRGB(180, 180, 180)
	heading.TextXAlignment = Enum.TextXAlignment.Left
	heading.Parent = row

	local box = Instance.new("TextBox")
	box.Size = UDim2.new(1, 0, 0, 25)
	box.BackgroundColor3 = Color3.fromRGB(17, 29, 52)
	box.BackgroundTransparency = 0.2
	box.Text = defaultValue
	box.Font = Enum.Font.SourceSans
	box.TextSize = 14
	box.TextColor3 = Color3.fromRGB(255, 255, 255)
	box.ClearTextOnFocus = false
	box.TextXAlignment = Enum.TextXAlignment.Center
	box.Parent = row

	local corner = Instance.new("UICorner")
	corner.CornerRadius = UDim.new(0, 5)
	corner.Parent = box

	local stroke = Instance.new("UIStroke")
	stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
	stroke.Color = Color3.fromRGB(43, 76, 125)
	stroke.Thickness = 1.0
	stroke.Transparency = 0.5
	stroke.Parent = box

	box.Focused:Connect(function()
		if pulsationTweens[box] then
			pulsationTweens[box]:Cancel()
		end

		local pulseInfo = TweenInfo.new(0.8, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true)
		pulsationTweens[box] = TweenService:Create(stroke, pulseInfo, {
			Color = Color3.fromRGB(32, 144, 255):Lerp(Color3.fromRGB(105, 206, 255), 0.5),
			Thickness = 1.5,
			Transparency = 0.2
		})
		pulsationTweens[box]:Play()
	end)

	box.FocusLost:Connect(function()
		if pulsationTweens[box] then
			pulsationTweens[box]:Cancel()
			pulsationTweens[box] = nil
		end

		TweenService:Create(stroke, TweenInfo.new(0.3, Enum.EasingStyle.Quad), {
			Color = Color3.fromRGB(43, 76, 125),
			Thickness = 1.0,
			Transparency = 0.5
		}):Play()
	end)

	return box, stroke, heading
end

-- ==============================================================
-- LOCAL FAKE KNIFE/GUN WEAR
-- ==============================================================
-- This creates a client-only visual copy of a weapon over the selected
-- player's currently equipped Knife/Gun.  It never fires a remote and does
-- not change the player's inventory, so nobody except the local client sees
-- the replacement.
--
-- MM2 does not keep every weapon in one fixed public folder.  Depending on
-- the round and client version, a renderable model can be in ReplicatedStorage,
-- Workspace, Lighting, or an executor's unparented-instance cache.  Build a
-- data-driven index once instead of assuming a path such as Assets.Weapons.
-- Prefer models replicated by MM2 itself.  For legacy weapons whose live row
-- exposes only a thumbnail, use visually matching public 3D models from the
-- Roblox Creator Store.  "Sorry" is MM2's internal key for Corrupt.
do
Runtime.weaponRepair = {version = 2, issues = {}, nativeSizes = {}, bounds = setmetatable({}, {__mode="k"})}
function Runtime.RepairTarget(key)
	local data = WeaponData[key]
	local name = tostring(data and data.ItemName or key):lower():gsub("[^%w]", "")
	name = name:gsub("^chroma", ""):gsub("chroma$", "")
	local targets = {celestial=true,heartwand=true,beachy=true,sands=true,
		constellation=true,darkshot=true,bat=true,zombiebat=true}
	return targets[name] == true
end
function Runtime.RepairIssue(key, message)
	if Runtime.weaponRepair.issues[key] ~= message then
		Runtime.weaponRepair.issues[key] = message
		warn("[Zoy0m/K1borg/model] " .. tostring(key) .. ": " .. message)
	end
end
function Runtime.AssetString(value)
	if type(value) ~= "string" then return false end
	local id = value:match("rbxassetid://(%d+)") or value:match("[?&]id=(%d+)")
	return id ~= nil and tonumber(id) ~= nil and tonumber(id) > 0
end
function Runtime.IsPreviewInstance(instance)
	local cursor = instance
	while cursor and cursor ~= game do
		if tostring(cursor.Name):find("__LocalFakeWear_",1,true) == 1 then return true end
		if tostring(cursor.Name):find("__MM2RealWeaponTemplateCache",1,true) == 1 then return true end
		if cursor:GetAttribute("MM2RealWeaponTemplate") ~= nil then return true end
		cursor = cursor.Parent
	end
	return false
end
function Runtime.TemplateScore(key,model,source,base)
	if not Runtime.RepairTarget(key) then return base end
	if source:find("pinned MM2 mesh database",1,true) then return base + 1000 end
	if source:find("Creator Store",1,true) then return base + 100 end
	return base + 2000
end
function Runtime.HasSurfaceMaps(props)
	if type(props) ~= "table" then return false end
	for _, field in ipairs({"ColorMap", "NormalMap", "RoughnessMap", "MetalnessMap"}) do
		if Runtime.AssetString(props[field]) then return true end
	end
	return false
end
function Runtime.ValidWeaponGeometry(model)
	if not model then return false end
	local nodes = model:GetDescendants()
	table.insert(nodes, 1, model)
	local meshes = 0
	for _, node in ipairs(nodes) do
		if node:IsA("MeshPart") then
			if not Runtime.AssetString(node.MeshId) then return false end
			meshes = meshes + 1
		elseif node:IsA("SpecialMesh") then
			if node.MeshType == Enum.MeshType.FileMesh then
				if not Runtime.AssetString(node.MeshId) then return false end
				meshes = meshes + 1
			end
		elseif node.ClassName == "FileMesh" then
			local ok, id = pcall(function() return node.MeshId end)
			if not ok or not Runtime.AssetString(id) then return false end
			meshes = meshes + 1
		end
	end
	return meshes > 0
end
function Runtime.StaticGeometryPresent(row)
	local meshes, invalid = 0, false
	local function visit(node)
		local props = node.Props or {}
		if node.Class == "FileMesh" then invalid = true end
		if node.Class == "MeshPart" or (node.Class == "SpecialMesh" and props.MeshType == Enum.MeshType.FileMesh) then
			if not Runtime.AssetString(props.MeshId) then invalid = true else meshes = meshes + 1 end
		end
		for _, child in ipairs(node.Children or {}) do visit(child) end
	end
	if row.Model then visit(row.Model)
	else for _, node in ipairs(row.Display or {}) do visit(node) end end
	return meshes > 0 and not invalid
end
function Runtime.RepairStaticSurface(instance, node)
	if not instance:IsA("MeshPart") then return end
	for _, child in ipairs(node.Children or {}) do
		if child.Class == "SurfaceAppearance" and not Runtime.HasSurfaceMaps(child.Props) then
			-- The dump omitted PBR maps. Do not install an empty override that hides
			-- the stored diffuse texture. This is explicitly a diffuse-only fallback.
			if Runtime.AssetString(instance.TextureID) then
				instance.Color = Color3.new(1, 1, 1)
				instance.Material = Enum.Material.SmoothPlastic
				instance:SetAttribute("MM2DiffuseFallback", true)
			else
				error("Surface maps and diffuse texture are both missing")
			end
		end
	end
end
function Runtime.WeaponBounds(model, anchor, transform)
	local minimum, maximum
	local cachedBounds = Runtime.weaponRepair.bounds[model]
	if cachedBounds then
		for _,point in ipairs(cachedBounds) do
			point = transform:PointToWorldSpace(point)
			minimum = minimum and Vector3.new(math.min(minimum.X,point.X),math.min(minimum.Y,point.Y),math.min(minimum.Z,point.Z)) or point
			maximum = maximum and Vector3.new(math.max(maximum.X,point.X),math.max(maximum.Y,point.Y),math.max(maximum.Z,point.Z)) or point
		end
		return minimum, maximum
	end
	local points = {}
	local nodes = model:GetDescendants()
	if model:IsA("BasePart") then table.insert(nodes, 1, model) end
	for _, part in ipairs(nodes) do
		if part:IsA("BasePart") and part.Transparency < 0.98 then
			local mesh = part:FindFirstChildOfClass("SpecialMesh")
			local extent, offset = part.Size, Vector3.new()
			if mesh then
				offset = mesh.Offset
				-- BasePart.Size is not the rendered size of a SpecialMesh.
				local cached = Runtime.weaponRepair.nativeSizes[mesh.MeshId]
				if cached == nil and Runtime.AssetString(mesh.MeshId) then
					cached = false
					pcall(function()
						local probe = game:GetService("AssetService"):CreateMeshPartAsync(Content.fromUri(mesh.MeshId))
						cached = probe.MeshSize
						probe:Destroy()
					end)
					Runtime.weaponRepair.nativeSizes[mesh.MeshId] = cached
				end
				if cached then
					extent = Vector3.new(cached.X * math.abs(mesh.Scale.X),
						cached.Y * math.abs(mesh.Scale.Y), cached.Z * math.abs(mesh.Scale.Z))
				end
			end
			local relative = anchor.CFrame:ToObjectSpace(part.CFrame)
			for x = -1, 1, 2 do for y = -1, 1, 2 do for z = -1, 1, 2 do
				local point = relative:PointToWorldSpace(offset
					+ Vector3.new(extent.X*x, extent.Y*y, extent.Z*z)*0.5)
				table.insert(points, point)
				point = transform:PointToWorldSpace(point)
				minimum = minimum and Vector3.new(math.min(minimum.X,point.X), math.min(minimum.Y,point.Y),math.min(minimum.Z,point.Z)) or point
				maximum = maximum and Vector3.new(math.max(maximum.X,point.X), math.max(maximum.Y,point.Y),math.max(maximum.Z,point.Z)) or point
			end end end
		end
	end
	Runtime.weaponRepair.bounds[model] = points
	return minimum, maximum
end
function Runtime.ClearBody(model, skinAnchor, mount, body, mode)
	local minimum, maximum = Runtime.WeaponBounds(model, skinAnchor, mount)
	if not minimum then return mount end
	local correction = Vector3.new()
	local gap = 0.12
	if mode:find("knife-side",1,true) then
		correction = Vector3.new(math.min(0,-body.Size.X*0.5-gap-maximum.X),0,0)
	elseif mode:find("knife-back",1,true) then
		correction = Vector3.new(0,0,math.max(0,body.Size.Z*0.5+gap-minimum.Z))
	elseif mode:find("gun-belt",1,true) then
		correction = Vector3.new(math.max(0,body.Size.X*0.5+gap-minimum.X),0,0)
	end
	return CFrame.new(correction) * mount
end


