	Sorry = 10091365017,
	Corrupt = 10091365017,

	-- Summer 2026 last-resort visual assets.  Exact models captured from the
	-- running MM2 client still win; these are reached only when the current
	-- client exposes neither a renderable model nor usable mesh fields.
	Beachy = 80424266775408,
	Sands = 84466510968548,
	ChromaBeachy = 140023380910743,
	BeachyChroma = 140023380910743,
	["Chroma Beachy"] = 140023380910743,
	ChromaSands = 88418187612477,
	SandsChroma = 88418187612477,
	["Chroma Sands"] = 88418187612477,
}

local ExternalFakeWearNormalizedModelIds = {
	sorry = 10091365017,
	corrupt = 10091365017,
	beachy = 80424266775408,
	sands = 84466510968548,
	chromabeachy = 140023380910743,
	chromasands = 88418187612477,
}

local function ExternalFakeWearNormalize(value)
	return string.gsub(string.lower(tostring(value or "")), "[^%w]", "")
end

local function ExternalFakeWearResolveModelId(itemKey, data)
	local aliases = {}
	local function addAlias(value)
		if value ~= nil and tostring(value) ~= "" then
			table.insert(aliases, value)
		end
	end
	addAlias(itemKey)
	if type(data) == "table" then
		addAlias(data.ItemName)
		addAlias(data.Name)
		addAlias(data.DisplayName)
	end
	local keyCompact = ExternalFakeWearNormalize(itemKey)
	local isChroma = (type(data) == "table" and data.Chroma == true)
		or string.find(keyCompact, "chroma", 1, true) ~= nil

	for _, alias in ipairs(aliases) do
		local compact = ExternalFakeWearNormalize(alias)
		if compact ~= "" then
			local base = string.gsub(compact, "^chroma", "")
			base = string.gsub(base, "chroma$", "")
			local lookup = isChroma and ("chroma" .. base) or base
			local id = ExternalFakeWearNormalizedModelIds[lookup]
			if id then return id end
		end
	end
	return ExternalFakeWearModelIds[itemKey]
		or (type(data) == "table" and ExternalFakeWearModelIds[data.ItemName])
end
