-- merge: FULL data (has .Model tree, e.g. Evergun/Evergreen/Gingerscope with
-- lights/scopes/beams) overrides the old flat data for the same key.
local MESHES = {}
for k, v in pairs(MESHES_OLD) do MESHES[k] = v end
for k, v in pairs(MESHES_FULL) do MESHES[k] = v end
MESHES_OLD, MESHES_FULL = nil, nil

return MESHES

end)()

local MM2StaticMeshState = {
    loaded = true,
    loading = false,
    data = MM2StaticMeshEmbeddedDatabase,
    aliases = nil,
    assetIds = nil,
    status = "loaded from embedded database",
}

local function MM2StaticMeshNormalize(value)
    return string.gsub(string.lower(tostring(value or "")), "[^%w]", "")
end

local function MM2StaticMeshAssetId(value)
    if value == nil then return nil end
    local last = nil
    for digits in string.gmatch(tostring(value), "%d+") do last = digits end
    return last and tonumber(last) or nil
end

local function MM2StaticMeshAddIndex(index, value, meshKey)
    if value == nil then return end
    local key = tostring(value)
    if key == "" then return end
    local bucket = index[key]
    if not bucket then bucket = {}; index[key] = bucket end
    for _, existing in ipairs(bucket) do
        if existing == meshKey then return end
    end
    table.insert(bucket, meshKey)
end

local function MM2StaticMeshBuildIndexes(database)
    local aliases, assetIds = {}, {}
    local processed = 0
    for meshKey, row in pairs(database) do
        processed = processed + 1
        if type(row) == "table" and (row.Model or row.Display) then
            local meta = type(row.Meta) == "table" and row.Meta or {}
            MM2StaticMeshAddIndex(aliases, MM2StaticMeshNormalize(meshKey), meshKey)
            MM2StaticMeshAddIndex(aliases, MM2StaticMeshNormalize(meta.ItemName), meshKey)
            MM2StaticMeshAddIndex(aliases, MM2StaticMeshNormalize(meta.Name), meshKey)
            MM2StaticMeshAddIndex(assetIds, MM2StaticMeshAssetId(meta.ItemID), meshKey)
            MM2StaticMeshAddIndex(assetIds, MM2StaticMeshAssetId(meta.Image), meshKey)
        end
        if processed % 75 == 0 then task.wait() end
    end
    MM2StaticMeshState.aliases = aliases
    MM2StaticMeshState.assetIds = assetIds
end

local function MM2StaticMeshLoad()
    if type(MM2StaticMeshState.data) ~= "table" then
        MM2StaticMeshState.status = "embedded mesh database unavailable"
        warn("[mm2run/mesh-db] embedded mesh database unavailable")
        return nil
    end
    if not MM2StaticMeshState.aliases or not MM2StaticMeshState.assetIds then
        MM2StaticMeshBuildIndexes(MM2StaticMeshState.data)
    end
    return MM2StaticMeshState.data
end

local function MM2StaticMeshRowIsChroma(meshKey, row)
	local meta = type(row) == "table" and row.Meta or nil
	if type(meta) == "table" and meta.Chroma == true then return true end
	local normalized = MM2StaticMeshNormalize(meshKey)
	return string.find(normalized, "chroma", 1, true) ~= nil
end

local function MM2StaticMeshChoose(database, keys, wantedType, wantedChroma, wantedAliases)
	local bestKey, bestScore = nil, -math.huge
	local seen = {}
	for _, meshKey in ipairs(keys or {}) do
		if not seen[meshKey] then
			seen[meshKey] = true
			local row = database[meshKey]
			if type(row) == "table" and MM2StaticMeshRowIsChroma(meshKey,row) == wantedChroma
				and (not wantedType or not row.Meta or not row.Meta.ItemType or row.Meta.ItemType == wantedType) then
				local meta = type(row.Meta) == "table" and row.Meta or {}
				local score = 0
				if wantedType then
					score = score + (meta.ItemType == wantedType and 100 or -100)
				end
				local rowChroma = MM2StaticMeshRowIsChroma(meshKey, row)
				score = score + (rowChroma == wantedChroma and 30 or -30)
				local keyAlias = MM2StaticMeshNormalize(meshKey)
				local nameAlias = MM2StaticMeshNormalize(meta.ItemName)
				if wantedAliases[keyAlias] then score = score + 60 end
				if wantedAliases[nameAlias] then score = score + 50 end
				if row.Model then score = score + 8 end
				if row.Complete == true then score = score + 4 end
				if score > bestScore then
					bestKey, bestScore = meshKey, score
				end
			end
		end
	end
	return bestKey
end

local function MM2StaticMeshResolve(itemKey)
	local database = MM2StaticMeshLoad()
	if not database then return nil end
	local live = WeaponData[itemKey]
	local wantedType = type(live) == "table" and live.ItemType or nil
	local wantedChroma = (type(live) == "table" and live.Chroma == true)
		or (string.find(MM2StaticMeshNormalize(itemKey), "chroma", 1, true) ~= nil)
	local wantedAliases, candidates = {}, {}
	local function addCandidate(value)
		if value == nil or tostring(value) == "" then return end
		local raw = tostring(value)
		wantedAliases[MM2StaticMeshNormalize(raw)] = true
		table.insert(candidates, raw)
	end
	addCandidate(itemKey)
	if type(live) == "table" then
		addCandidate(live.ItemName)
		addCandidate(live.Name)
		addCandidate(live.DisplayName)
	end
	if itemKey == "Sorry" then addCandidate("Corrupt") end
	if itemKey == "Bat" or (live and live.ItemName == "Bat") then addCandidate("ZombieBat") end

	-- Exact keys are unambiguous and should always win.
	for _, candidate in ipairs(candidates) do
		local row = database[candidate]
		if type(row) == "table" and MM2StaticMeshRowIsChroma(candidate,row) == wantedChroma and (not wantedType
			or not row.Meta or not row.Meta.ItemType or row.Meta.ItemType == wantedType) then
			return candidate, row
		end
	end

	-- Match immutable item/image ids before names.  This also resolves internal
	-- MM2 keys whose public display name changed between client versions.
	local idCandidates = {}
	if type(live) == "table" then
		for field, value in pairs(live) do
			local lowerField = string.lower(tostring(field))
			if string.find(lowerField, "id", 1, true)
				or string.find(lowerField, "image", 1, true) then
				local id = MM2StaticMeshAssetId(value)
				for _, meshKey in ipairs((id and MM2StaticMeshState.assetIds[tostring(id)]) or {}) do
					table.insert(idCandidates, meshKey)
				end
			end
		end
	end
	local idMatch = MM2StaticMeshChoose(database, idCandidates, wantedType, wantedChroma, wantedAliases)
	if idMatch then return idMatch, database[idMatch] end

	local aliasCandidates = {}
	for alias in pairs(wantedAliases) do
		for _, meshKey in ipairs(MM2StaticMeshState.aliases[alias] or {}) do
			table.insert(aliasCandidates, meshKey)
		end
		local base = string.gsub(alias, "^chroma", "")
		base = string.gsub(base, "chroma$", "")
		if base ~= alias and base ~= "" then
			for _, variant in ipairs({base, "chroma" .. base, base .. "chroma"}) do
				for _, meshKey in ipairs(MM2StaticMeshState.aliases[variant] or {}) do
					table.insert(aliasCandidates, meshKey)
				end
			end
		end
	end
	local aliasMatch = MM2StaticMeshChoose(database, aliasCandidates, wantedType, wantedChroma, wantedAliases)
	if aliasMatch then return aliasMatch, database[aliasMatch] end
	return nil
end

local function MM2StaticMeshTrimAsset(value)
	if type(value) == "string" then
		return (string.gsub(string.gsub(value, "^%s+", ""), "%s+$", ""))
	end
	return value
end

local function MM2StaticMeshApplyProps(instance, props, skip)
	if not instance or type(props) ~= "table" then return end
	for property, value in pairs(props) do
		if not (skip and skip[property]) then
			if property == "MeshId" or property == "TextureId"
				or property == "TextureID" or property == "Texture" then
				value = MM2StaticMeshTrimAsset(value)
			end
			pcall(function() instance[property] = value end)
		end
	end
end

local function MM2StaticMeshCreateMeshPart(props)
	props = type(props) == "table" and props or {}
	local meshId = MM2StaticMeshTrimAsset(props.MeshId or "")
	assert(meshId ~= "", "Missing mesh ID")
	local size = props.Size or Vector3.new(1, 1, 1)
	local meshPart
	pcall(function()
		meshPart = game:GetService("AssetService"):CreateMeshPartAsync(Content.fromUri(meshId), {
			CollisionFidelity = Enum.CollisionFidelity.Box,
			RenderFidelity = Enum.RenderFidelity.Precise,
		})
	end)
	if not meshPart then
		-- Legacy compatibility, with identity restored after both success and failure.
		local previousIdentity
		if type(getthreadidentity) == "function" then pcall(function() previousIdentity = getthreadidentity() end) end
		if type(setthreadidentity) == "function" then pcall(setthreadidentity, 2) end
		pcall(function()
			meshPart = game:GetService("InsertService"):CreateMeshPartAsync(meshId,
				Enum.CollisionFidelity.Box, Enum.RenderFidelity.Precise)
		end)
		if type(setthreadidentity) == "function" then pcall(setthreadidentity, previousIdentity or 8) end
	end
	assert(meshPart, "Mesh unavailable: " .. tostring(meshId) .. "; keeping the original weapon")
	meshPart.Size = size
	return meshPart
end

local MM2StaticMeshStructural = {
	WeldConstraint = true, Weld = true, Motor6D = true, RigidConstraint = true,
	Bone = true, Snap = true, ManualWeld = true, Rotate = true,
	RotateP = true, RotateV = true,
}

local function MM2StaticMeshCopyChromaTag(instance, node)
	if not instance or type(node.Tags) ~= "table" then return end
	for _, tag in ipairs(node.Tags) do
		local role = (tag == "ChromaPart" and "part")
			or (tag == "ChromaDecal" and "decal")
			or (tag == "ChromaFire" and "fire")
		if role then pcall(function() instance:SetAttribute("MM2Chroma", role) end) end
	end
end

local function MM2StaticMeshInstantiateNode(node)
	if type(node) ~= "table" or MM2StaticMeshStructural[node.Class] then return nil end
	if node.Class == "Script" or node.Class == "LocalScript" or node.Class == "ModuleScript" then return nil end
	if node.Class == "SurfaceAppearance" and not Runtime.HasSurfaceMaps(node.Props) then return nil end
	local instance = nil
	if node.Class == "MeshPart" then
		instance = MM2StaticMeshCreateMeshPart(node.Props)
		MM2StaticMeshApplyProps(instance, node.Props, {
			MeshId = true, Size = true, RelCF = true, CanCollide = true,
		})
	else
		local ok, created = pcall(Instance.new, node.Class)
		if not ok or not created then return nil end
		instance = created
		MM2StaticMeshApplyProps(instance, node.Props, {RelCF = true})
	end
	pcall(function() instance.Name = node.Name or instance.Name end)
	MM2StaticMeshCopyChromaTag(instance, node)
	Runtime.RepairStaticSurface(instance, node)
	return instance
end

local function MM2StaticMeshRebuildTree(node, parentInstance, root, idToInstance, parts, deferred)
	for _, child in ipairs(node.Children or {}) do
		local instance = MM2StaticMeshInstantiateNode(child)
		if instance then
			if child.Id ~= nil then idToInstance[child.Id] = instance end
			if instance:IsA("BasePart") then
				instance.Anchored = true
				instance.CanCollide = false
				instance.CanQuery = false
				instance.CanTouch = false
				instance.Massless = true
				table.insert(parts, {instance = instance, relcf = child.Props and child.Props.RelCF})
				instance.Parent = root
				MM2StaticMeshRebuildTree(child, instance, root, idToInstance, parts, deferred)
			elseif instance:IsA("Attachment") then
				if child.Props and child.Props.RelCF then
					pcall(function() instance.CFrame = child.Props.RelCF end)
				end
				instance.Parent = root
				MM2StaticMeshRebuildTree(child, instance, root, idToInstance, parts, deferred)
			elseif instance:IsA("Beam") or instance:IsA("Trail") then
				instance.Parent = parentInstance
				table.insert(deferred, {instance = instance, a0 = child.Att0, a1 = child.Att1})
				MM2StaticMeshRebuildTree(child, instance, root, idToInstance, parts, deferred)
			else
				instance.Parent = parentInstance
				MM2StaticMeshRebuildTree(child, instance, root, idToInstance, parts, deferred)
			end
		else
			MM2StaticMeshRebuildTree(child, parentInstance, root, idToInstance, parts, deferred)
		end
	end
end

local function MM2StaticMeshBuildFull(row)
	local rootNode = row.Model
	if type(rootNode) ~= "table" then return nil end
	local root = nil
	if rootNode.Class == "MeshPart" then
		root = MM2StaticMeshCreateMeshPart(rootNode.Props)
		MM2StaticMeshApplyProps(root, rootNode.Props, {
			MeshId = true, Size = true, RelCF = true, CanCollide = true,
		})
	else
		local ok, created = pcall(Instance.new, rootNode.Class or "Part")
		root = ok and created or Instance.new("Part")
		if not root:IsA("BasePart") then
			root:Destroy()
			root = Instance.new("Part")
		end
		MM2StaticMeshApplyProps(root, rootNode.Props, {RelCF = true, CanCollide = true})
	end
	Runtime.RepairStaticSurface(root, rootNode)
	root.Name = rootNode.Name or "WeaponDisplay"
	MM2StaticMeshCopyChromaTag(root, rootNode)
	root.Anchored = true
	root.CanCollide = false
	root.CanQuery = false
	root.CanTouch = false
	root.Massless = true

	local idToInstance = {}
	if rootNode.Id ~= nil then idToInstance[rootNode.Id] = root end
	local parts, deferred = {}, {}
	MM2StaticMeshRebuildTree(rootNode, root, root, idToInstance, parts, deferred)
	for _, link in ipairs(deferred) do
		if link.a0 and idToInstance[link.a0] then
			pcall(function() link.instance.Attachment0 = idToInstance[link.a0] end)
		end
		if link.a1 and idToInstance[link.a1] then
			pcall(function() link.instance.Attachment1 = idToInstance[link.a1] end)
		end
	end
	return {root = root, parts = parts}
end

local MM2StaticMeshEffectClasses = {
	ParticleEmitter = true, Fire = true, Smoke = true, Sparkles = true,
	PointLight = true, SpotLight = true, SurfaceLight = true,
}

local function MM2StaticMeshBuildFlat(row)
	local rootData, meshes, decals, effects = nil, {}, {}, {}
	for _, entry in ipairs(row.Display or {}) do
		if entry.Path == "(root)" then
			rootData = entry
		elseif entry.Class == "SpecialMesh" then
			table.insert(meshes, entry)
		elseif entry.Class == "Decal" or entry.Class == "Texture" then
			table.insert(decals, entry)
		elseif MM2StaticMeshEffectClasses[entry.Class] then
			table.insert(effects, entry)
		end
	end
	if not rootData then return nil end

	local root = nil
	if rootData.Class == "MeshPart" then
		root = MM2StaticMeshCreateMeshPart(rootData.Props)
		MM2StaticMeshApplyProps(root, rootData.Props, {
			MeshId = true, Size = true, CanCollide = true,
		})
	else
		root = Instance.new("Part")
		root.Size = (rootData.Props and rootData.Props.Size) or Vector3.new(1, 1, 1)
		MM2StaticMeshApplyProps(root, rootData.Props, {Size = true, CanCollide = true})
		for _, meshData in ipairs(meshes) do
			local mesh = Instance.new("SpecialMesh")
			mesh.MeshType = Enum.MeshType.FileMesh
			MM2StaticMeshApplyProps(mesh, meshData.Props)
			mesh.Parent = root
		end
	end
	root.Name = rootData.Name or "WeaponDisplay"
	root.Anchored = true
	root.CanCollide = false
	root.CanQuery = false
	root.CanTouch = false
	root.Massless = true
	for _, decalData in ipairs(decals) do
		local ok, decal = pcall(Instance.new, decalData.Class)
		if ok and decal then
			MM2StaticMeshApplyProps(decal, decalData.Props)
			decal.Name = decalData.Name or decal.Name
			decal.Parent = root
		end
	end
	for _, effectData in ipairs(effects) do
		local ok, effect = pcall(Instance.new, effectData.Class)
		if ok and effect then
			MM2StaticMeshApplyProps(effect, effectData.Props)
			effect.Name = effectData.Name or effect.Name
			effect.Parent = root
		end
	end
	return {root = root, parts = {}}
end

local function MM2StaticMeshBuildTemplate(itemKey, meshKey, row)
	if Runtime.RepairTarget(itemKey) and not Runtime.StaticGeometryPresent(row) then
		Runtime.RepairIssue(itemKey,"Mesh data incomplete; searching for a real client model")
		return nil
	end
	local built = row.Model and MM2StaticMeshBuildFull(row) or MM2StaticMeshBuildFlat(row)
	if not built or not built.root then return nil end
	local root = built.root
	pcall(function() root.CFrame = CFrame.new() end)
	for _, partInfo in ipairs(built.parts or {}) do
		if partInfo.relcf then
			pcall(function() partInfo.instance.CFrame = partInfo.relcf end)
		end
		local weld = Instance.new("WeldConstraint")
		weld.Part0 = partInfo.instance
		weld.Part1 = root
		weld.Parent = partInfo.instance
	end

	local model = Instance.new("Model")
	model.Name = "__MM2Static_" .. string.gsub(tostring(itemKey), "[^%w_]", "_")
	root.Parent = model
	model.PrimaryPart = root
	model:SetAttribute("MM2StaticMeshKey", tostring(meshKey))
	model:SetAttribute("MM2StaticChroma", MM2StaticMeshRowIsChroma(meshKey, row))
	model:SetAttribute("MM2StaticComplete", row.Complete == true)
	if row.Complete ~= true then
		warn("[Zoy0m/K1borg] Partial model data for " .. tostring(itemKey) .. "; appearance may differ.")
	end
	return model
end

local MM2StaticChromaColors = {
	Color3.fromRGB(255, 0, 0), Color3.fromRGB(255, 255, 0),
	Color3.fromRGB(0, 255, 0), Color3.fromRGB(0, 255, 255),
	Color3.fromRGB(0, 0, 255), Color3.fromRGB(255, 0, 255),
}
local MM2StaticChromaLayer = "rbxassetid://18363392181"

local function MM2StaticMeshStartChroma(overlay, itemKey)
	if not overlay then return nil end
	local live = WeaponData[itemKey]
	local enabled = (overlay:GetAttribute("MM2StaticChroma") == true)
		or (type(live) == "table" and live.Chroma == true)
		or (string.find(MM2StaticMeshNormalize(itemKey), "chroma", 1, true) ~= nil)
	if not enabled then return nil end

	local flashParts, smoothDecals, smoothOther = {}, {}, {}
	local visualRoot = overlay:IsA("BasePart") and overlay
		or (overlay:IsA("Model") and (overlay.PrimaryPart or overlay:FindFirstChildWhichIsA("BasePart", true)))
		or overlay:FindFirstChildWhichIsA("BasePart", true)
	local tagged = false
	local all = {overlay}
	for _, descendant in ipairs(overlay:GetDescendants()) do table.insert(all, descendant) end
	for _, instance in ipairs(all) do
		local role = instance:GetAttribute("MM2Chroma")
		if role then
			tagged = true
			if role == "part" and instance:IsA("BasePart") then
				table.insert(flashParts, instance)
			elseif role == "decal" and instance:IsA("Decal") then
				pcall(function() instance.Texture = MM2StaticChromaLayer end)
				table.insert(smoothDecals, instance)
			elseif role == "fire" and instance:IsA("Fire") then
				table.insert(smoothOther, instance)
			end
		end
	end
	if not tagged then
		for _, instance in ipairs(all) do
			if instance:IsA("BasePart") and (instance.Material == Enum.Material.Neon
				or string.find(string.lower(instance.Name), "light", 1, true)) then
				table.insert(flashParts, instance)
			elseif instance:IsA("Decal") and string.find(string.lower(instance.Name), "chroma", 1, true) then
				table.insert(smoothDecals, instance)
			elseif instance:IsA("Fire") then
				table.insert(smoothOther, instance)
			end
		end
		if #smoothDecals == 0 and visualRoot then table.insert(smoothOther, visualRoot) end
	end
	if #flashParts == 0 and #smoothDecals == 0 and #smoothOther == 0 then return nil end

	local lastColorAt = 0
	return game:GetService("RunService").Heartbeat:Connect(function()
		if not overlay.Parent then return end
		local now = os.clock()
		if now-lastColorAt < 1/20 then return end
		lastColorAt = now
		local phase = now % #MM2StaticChromaColors
		local index = math.floor(phase)
		local color = MM2StaticChromaColors[index + 1]:Lerp(
			MM2StaticChromaColors[((index + 1) % #MM2StaticChromaColors) + 1], phase - index)
		for _, instance in ipairs(smoothDecals) do
			pcall(function() instance.Color3 = color end)
		end
		for _, instance in ipairs(smoothOther) do
			pcall(function()
				if instance:IsA("Fire") then instance.Color = color
				elseif instance:IsA("BasePart") then instance.Color = color end
			end)
		end
		local step = math.floor(now * 1.8)
		for i, instance in ipairs(flashParts) do
			pcall(function()
				instance.Color = MM2StaticChromaColors[((step + i - 1) % #MM2StaticChromaColors) + 1]
			end)
		end
	end)
end

local MM2TemplateCache = game:GetService("ReplicatedStorage"):FindFirstChild("__MM2RealWeaponTemplateCache_v2")
if not MM2TemplateCache or not MM2TemplateCache:IsA("Folder") then
	MM2TemplateCache = Instance.new("Folder")
	MM2TemplateCache.Name = "__MM2RealWeaponTemplateCache_v2"
	MM2TemplateCache.Parent = game:GetService("ReplicatedStorage")
end

Runtime.requestedModels = {}
local MM2VisualParser = {
	built = false,
	building = false,
	aliases = {},
	normalizedAliases = {},
	weaponKeys = {},
	models = {},
	snapshots = {},
	report = {},
	rendererAttempts = {},
	assetAttempts = {},
	dataMeshAttempts = {},
	staticMeshAttempts = {},
	externalModelAttempts = {},
	externalObjects = {},
	watchConnections = {},
}

local function MM2VisualParserFirstPart(root)
	if not root then return nil end
	if root:IsA("BasePart") then return root end
	local handle = root:FindFirstChild("Handle", true)
	if handle and handle:IsA("BasePart") then return handle end
	if root:IsA("Model") and root.PrimaryPart then return root.PrimaryPart end
	for _, desc in ipairs(root:GetDescendants()) do
		if desc:IsA("BasePart") then return desc end
	end
	return nil
end

local function MM2VisualParserAddAlias(alias, itemKey)
	if alias and alias ~= "" then
		local lower = string.lower(tostring(alias))
		local old = MM2VisualParser.aliases[lower]
		MM2VisualParser.aliases[lower] = (old == nil or old == itemKey) and itemKey or false
		local normalized = string.gsub(lower, "[^%w]", "")
		if normalized ~= "" then
			local previous = MM2VisualParser.normalizedAliases[normalized]
			if previous == nil or previous == itemKey then
				MM2VisualParser.normalizedAliases[normalized] = itemKey
			else
				-- Ambiguous display names must never resolve to the wrong skin.
				MM2VisualParser.normalizedAliases[normalized] = false
			end
		end
	end
end

local function MM2VisualParserResolveAlias(value)
	if value == nil then return nil end
	local lower = string.lower(tostring(value))
	if not Runtime.weaponKeysLower then
		Runtime.weaponKeysLower = {}
		for key in pairs(WeaponData) do Runtime.weaponKeysLower[string.lower(tostring(key))] = key end
	end
	if Runtime.weaponKeysLower[lower] then return Runtime.weaponKeysLower[lower] end
	local exact = MM2VisualParser.aliases[lower]
	if exact then return exact end
	local normalized = string.gsub(lower, "[^%w]", "")
	local resolved = MM2VisualParser.normalizedAliases[normalized]
	return type(resolved) == "string" and resolved or nil
end

local function MM2VisualParserBuildAliases()
	if next(MM2VisualParser.aliases) then return end
	for itemKey, data in pairs(WeaponData) do
		if type(data) == "table" and (data.ItemType == "Knife" or data.ItemType == "Gun") then
			MM2VisualParser.weaponKeys[itemKey] = true
			MM2VisualParserAddAlias(itemKey, itemKey)
			MM2VisualParserAddAlias(data.ItemName, itemKey)
			MM2VisualParserAddAlias(data.Name, itemKey)
			MM2VisualParserAddAlias(data.DisplayName, itemKey)
		end
	end
end

local function MM2VisualParserRank(instance)
	local score = 100
	if instance:IsA("Model") then score = 600
	elseif instance:IsA("Tool") or instance:IsA("Accessory") then score = 500
	elseif instance:IsA("Folder") then score = 400
	elseif instance:IsA("BasePart") then score = 300 end
	local partCount = instance:IsA("BasePart") and 1 or 0
	for _, desc in ipairs(instance:GetDescendants()) do
		if desc:IsA("BasePart") then partCount = partCount + 1 end
	end
	return score + math.min(partCount, 99)
end

local function MM2VisualParserIsInsideCache(instance)
	if not instance or instance == MM2TemplateCache then return instance == MM2TemplateCache end
	local ok, result = pcall(function() return instance:IsDescendantOf(MM2TemplateCache) end)
	return ok and result
end

local function MM2VisualParserResolveInstanceKey(instance)
	if typeof(instance) ~= "Instance" then return nil end
	local itemKey = MM2VisualParserResolveAlias(instance.Name)
	if itemKey then return itemKey end

	if instance:IsA("Tool") then
		itemKey = MM2VisualParserResolveAlias(instance.ToolTip)
		if itemKey then return itemKey end
	end

	if instance:IsA("ValueBase") then
		local ok, value = pcall(function() return instance.Value end)
		if ok then
			itemKey = MM2VisualParserResolveAlias(value)
			if itemKey then return itemKey end
		end
	end

	local ok, attributes = pcall(function() return instance:GetAttributes() end)
	if ok then
		for attributeName, value in pairs(attributes) do
			itemKey = MM2VisualParserResolveAlias(attributeName)
				or MM2VisualParserResolveAlias(value)
			if itemKey then return itemKey end
		end
	end

	for _, child in ipairs(instance:GetChildren()) do
		if child:IsA("ValueBase") then
			local valueOk, value = pcall(function() return child.Value end)
			if valueOk then
				itemKey = MM2VisualParserResolveAlias(child.Name)
					or MM2VisualParserResolveAlias(value)
				if itemKey then return itemKey end
			end
		end
	end
	return nil
end

function MM2VisualParser.FindKeyForInstance(instance)
	local cursor = instance
	for _ = 1, 7 do
		if not cursor or cursor == game then break end
		local itemKey = MM2VisualParserResolveInstanceKey(cursor)
		if itemKey then return itemKey end
		cursor = cursor.Parent
	end
	return nil
end

local function MM2VisualParserRenderableRoot(instance)
	if typeof(instance) ~= "Instance" then return nil end
	if (instance:IsA("Model") or instance:IsA("Tool") or instance:IsA("Accessory")
		or instance:IsA("Folder")) and MM2VisualParserFirstPart(instance) then
		if not (instance:IsA("Model") and instance:FindFirstChildOfClass("Humanoid")) then
			return instance
		end
	end

	local fallback = instance:IsA("BasePart") and instance or nil
	local cursor = instance.Parent
	for _ = 1, 7 do
		if not cursor or cursor == game or cursor == workspace
			or cursor == game:GetService("ReplicatedStorage")
			or cursor == game:GetService("Lighting") then break end
		if cursor:IsA("Tool") or cursor:IsA("Accessory") then
			if MM2VisualParserFirstPart(cursor) then return cursor end
		elseif cursor:IsA("Model") then
			if cursor:FindFirstChildOfClass("Humanoid") then break end
			if MM2VisualParserFirstPart(cursor) then return cursor end
		elseif cursor:IsA("Folder") and MM2VisualParserResolveAlias(cursor.Name) then
			if MM2VisualParserFirstPart(cursor) then return cursor end
		end
		cursor = cursor.Parent
	end
	return fallback
end

local function MM2VisualParserCacheTemplate(itemKey, instance)
	if MM2VisualParserIsInsideCache(instance) then return instance end
	local ok, clone = pcall(function() return instance:Clone() end)
	if not ok or not clone or not MM2VisualParserFirstPart(clone) then
		if clone then clone:Destroy() end
		return instance
	end

	for _, desc in ipairs(clone:GetDescendants()) do
		if desc:IsA("Script") or desc:IsA("LocalScript") or desc:IsA("ModuleScript") then
			desc:Destroy()
		end
	end
	clone.Name = "__RealTemplate_" .. string.gsub(tostring(itemKey), "[^%w_]", "_")
	pcall(function() clone:SetAttribute("MM2RealWeaponTemplate", itemKey) end)
	clone.Parent = MM2TemplateCache

	local previous = MM2VisualParser.snapshots[itemKey]
	MM2VisualParser.snapshots[itemKey] = clone
	if previous and previous ~= clone and previous.Parent == MM2TemplateCache then
		previous:Destroy()
	end
	return clone
end

local function MM2VisualParserRecord(itemKey, instance, source)
	if not Runtime.alive then return end
	if not itemKey or not instance or not Runtime.requestedModels[itemKey] then return end
	local root = MM2VisualParserRenderableRoot(instance)
	if not root or not MM2VisualParserFirstPart(root) then return end
	if Runtime.IsPreviewInstance(root) then return end
	if Runtime.RepairTarget(itemKey) and not Runtime.ValidWeaponGeometry(root) then
		Runtime.RepairIssue(itemKey,"Rejected placeholder geometry from " .. tostring(source))
		return
	end
	local score = Runtime.TemplateScore(itemKey,root,source,MM2VisualParserRank(root))
	local old = MM2VisualParser.models[itemKey]
	if old and old.instance and old.instance.Parent and (old.score or MM2VisualParserRank(old.instance)) >= score then
		return
	end
	local template = MM2VisualParserCacheTemplate(itemKey, root)
	if template ~= root then template:SetAttribute("MM2TemplateSource",source) end
	MM2VisualParser.models[itemKey] = {instance = template, source = source, score = score}
	MM2VisualParser.report[itemKey] = source .. " :: " .. root:GetFullName()
end

local function MM2VisualParserScanInstanceTree(root, source)
	if root ~= MM2TemplateCache and not MM2VisualParserIsInsideCache(root) then
		local rootKey = MM2VisualParser.FindKeyForInstance(root)
		if rootKey then MM2VisualParserRecord(rootKey, root, source) end
	end
	local scanned = 0
	for _, instance in ipairs(root:GetDescendants()) do
		scanned = scanned + 1
		if not MM2VisualParserIsInsideCache(instance) then
			local itemKey = MM2VisualParser.FindKeyForInstance(instance)
			if itemKey then
				MM2VisualParserRecord(itemKey, instance, source)
			end
		end
		if scanned % 100 == 0 then task.wait() end
	end
end

local function MM2VisualParserScanTables()
	if not getgc then return end
	pcall(function()
		local scanned = 0
		for _, object in ipairs(getgc(true)) do
			scanned = scanned + 1
			if type(object) == "table" then
				for tableKey, value in pairs(object) do
					local itemKey = type(tableKey) == "string"
						and MM2VisualParserResolveAlias(tableKey) or nil
					if itemKey and typeof(value) == "Instance" then
						MM2VisualParserRecord(itemKey, value, "getgc table")
					elseif itemKey and type(value) == "table" then
						for _, field in ipairs({"Model", "model", "Asset", "asset", "Instance", "instance"}) do
							local candidate = rawget(value, field)
							if typeof(candidate) == "Instance" then
								MM2VisualParserRecord(itemKey, candidate, "getgc table." .. field)
							end
						end
					end
				end
			end
			if scanned % 250 == 0 then task.wait() end
		end
	end)
end

function MM2VisualParser.Build(force)
	if MM2VisualParser.building or (MM2VisualParser.built and not force) then return end
	MM2VisualParser.building = true
	MM2VisualParser.aliases = {}
	MM2VisualParser.normalizedAliases = {}
	MM2VisualParser.weaponKeys = {}
	MM2VisualParser.models = {}
	MM2VisualParser.report = {}
	MM2VisualParserBuildAliases()
	for itemKey, snapshot in pairs(MM2VisualParser.snapshots) do
		if snapshot and snapshot.Parent == MM2TemplateCache and MM2VisualParserFirstPart(snapshot) then
			local source = snapshot:GetAttribute("MM2TemplateSource") or "captured real client model"
			MM2VisualParser.models[itemKey] = {
				instance = snapshot,
				source = source,
				score = Runtime.TemplateScore(itemKey,snapshot,source,MM2VisualParserRank(snapshot)),
			}
			MM2VisualParser.report[itemKey] = source .. " :: " .. snapshot:GetFullName()
		else
			MM2VisualParser.snapshots[itemKey] = nil
		end
	end

	local roots = {
		{instance = game:GetService("ReplicatedStorage"), name = "ReplicatedStorage"},
		{instance = workspace, name = "Workspace"},
		{instance = game:GetService("Lighting"), name = "Lighting"},
	}
	for _, root in ipairs(roots) do
		pcall(function() MM2VisualParserScanInstanceTree(root.instance, root.name) end)
	end

	pcall(function()
		if not getnilinstances then return end
		for _, instance in ipairs(getnilinstances()) do
			local itemKey = MM2VisualParser.FindKeyForInstance(instance)
			if itemKey then MM2VisualParserRecord(itemKey, instance, "getnilinstances") end
		end
	end)
	-- No getgc whole-heap scan during normal wardrobe use.

	MM2VisualParser.built = true
	MM2VisualParser.building = false
	local indexed = 0
	for _ in pairs(MM2VisualParser.models) do indexed = indexed + 1 end
	print(("[mm2run/mm2-parse] indexed %d renderable weapon models from the current client"):format(indexed))
end

function MM2VisualParser.StartWatching()
	if not Runtime.alive or #MM2VisualParser.watchConnections > 0 then return end
	MM2VisualParserBuildAliases()
	local pending, pendingCount, draining = {}, 0, false
	local function enqueue(instance, source)
		if not Runtime.alive or pending[instance] or pendingCount >= 256 then return end
		if not (instance:IsA("Model") or instance:IsA("Tool") or instance:IsA("BasePart")
			or instance:IsA("Accessory")) then return end
		if MM2VisualParserIsInsideCache(instance) or Runtime.IsPreviewInstance(instance) then return end
		pending[instance] = source
		pendingCount = pendingCount + 1
		if draining then return end
		draining = true
		task.defer(function()
			local batch = 0
			while Runtime.alive and pendingCount > 0 do
				local node, origin = next(pending)
				if not node then break end
				pending[node] = nil
				pendingCount = pendingCount - 1
				pcall(function()
					if node.Parent and not MM2VisualParserIsInsideCache(node) and not Runtime.IsPreviewInstance(node) then
						local key = MM2VisualParser.FindKeyForInstance(node)
						if key and Runtime.requestedModels[key] then MM2VisualParserRecord(key,node,origin) end
					end
				end)
				batch = batch + 1
				if batch % 24 == 0 then task.wait() end
			end
			table.clear(pending)
			pendingCount, draining = 0, false
		end)
	end
	for _, name in ipairs({"ReplicatedStorage","Workspace","Lighting"}) do
		local root = game:GetService(name)
		table.insert(MM2VisualParser.watchConnections, root.DescendantAdded:Connect(function(instance)
			enqueue(instance, name .. " live")
		end))
	end
end

function MM2VisualParser.Get(itemKey)
	if not Runtime.alive then return nil end
	Runtime.requestedModels[itemKey] = true
	MM2VisualParser.StartWatching()
	local entry = MM2VisualParser.models[itemKey]
	if entry and entry.instance and MM2VisualParserFirstPart(entry.instance) then
		return entry.instance, entry.source
	end
	MM2VisualParser.Build()
	entry = MM2VisualParser.models[itemKey]
	if entry and entry.instance and MM2VisualParserFirstPart(entry.instance) then
		return entry.instance, entry.source
	end
	return nil
end

function MM2VisualParser.Report(itemKey)
	MM2VisualParser.Build()
	local data = WeaponData[itemKey]
	local found = MM2VisualParser.report[itemKey] or "3D model not present in the local client cache"
	print(("[mm2run/mm2-parse] %s | type=%s | %s"):format(
		tostring(itemKey), tostring(data and data.ItemType), found))
	if type(data) == "table" then
		local fields = {}
		for field, value in pairs(data) do
			if type(value) == "string" or type(value) == "number" or type(value) == "boolean" then
				table.insert(fields, tostring(field) .. "=" .. tostring(value))
			end
		end
		table.sort(fields)
		print("[mm2run/mm2-parse] data " .. tostring(itemKey) .. " :: " .. table.concat(fields, " | "))
	end
	return found
end

-- Build an exact client-only weapon from the pinned MM2 mesh database.  This
-- covers the full Knife/Gun catalog represented by the data file, including
-- multi-part models and chroma/effect tags, without changing server inventory.
function MM2VisualParser.TryCreateFromStaticMeshData(itemKey)
	if not itemKey or itemKey == "" then return nil end
	local existing = MM2VisualParser.models[itemKey]
	if existing and existing.instance and existing.instance.Parent
		and MM2VisualParserFirstPart(existing.instance) then
		return existing.instance
	end

	MM2VisualParser.staticMeshAttempts = MM2VisualParser.staticMeshAttempts or {}
	local lastAttempt = MM2VisualParser.staticMeshAttempts[itemKey]
	if type(lastAttempt) == "number" and os.clock() - lastAttempt < 15 then return nil end
	MM2VisualParser.staticMeshAttempts[itemKey] = os.clock()

	local meshKey, row = MM2StaticMeshResolve(itemKey)
	if not meshKey or type(row) ~= "table" then
		print(("[mm2run/mesh-db] no matching 3D row for %s | %s"):format(
			tostring(itemKey), tostring(MM2StaticMeshState.status)))
		return nil
	end

	local buildOk, builtOrError = pcall(function()
		return MM2StaticMeshBuildTemplate(itemKey, meshKey, row)
	end)
	if not buildOk or not builtOrError then
		warn(("[mm2run/mesh-db] couldn't build %s from %s: %s"):format(
			tostring(itemKey), tostring(meshKey), tostring(buildOk and "empty model" or builtOrError)))
		return nil
	end

	local built = builtOrError
	local live = WeaponData[itemKey]
	pcall(function()
		built:SetAttribute("MM2WeaponKey", tostring(itemKey))
		built:SetAttribute("MM2MeshDataKey", tostring(meshKey))
		if type(live) == "table" and live.ItemType then
			built:SetAttribute("ItemType", tostring(live.ItemType))
		elseif type(row.Meta) == "table" and row.Meta.ItemType then
			built:SetAttribute("ItemType", tostring(row.Meta.ItemType))
		end
	end)

	MM2VisualParserRecord(itemKey, built, "pinned MM2 mesh database :: " .. tostring(meshKey))
	pcall(function() built:Destroy() end)

	local entry = MM2VisualParser.models[itemKey]
	if entry and entry.instance and entry.instance.Parent and MM2VisualParserFirstPart(entry.instance) then
		print(("[mm2run/mesh-db] built %s from exact row %s"):format(
			tostring(itemKey), tostring(meshKey)))
		return entry.instance
	end
	return nil
end

function MM2VisualParser.GetStaticMeshStatus()
	return MM2StaticMeshState.status
end
MM2VisualParser.StaticMeshState = MM2StaticMeshState

function MM2VisualParser.TryLoadExternalReplacement(itemKey)
	local attemptedAt = MM2VisualParser.externalModelAttempts[itemKey]
	if attemptedAt and (type(attemptedAt) ~= "number" or os.clock()-attemptedAt < 20) then return nil end
	MM2VisualParser.externalModelAttempts[itemKey] = os.clock()
	MM2VisualParserBuildAliases()

	local data = WeaponData[itemKey]
	local modelId = ExternalFakeWearResolveModelId(itemKey, data)
	if modelId then
		local ok, objects = pcall(function()
			return game:GetObjects("rbxassetid://" .. tostring(modelId))
		end)
		if ok and type(objects) == "table" then
			for _, object in ipairs(objects) do
				MM2VisualParserRecord(itemKey, object, "Creator Store fallback model " .. tostring(modelId))
			end
			local entry = MM2VisualParser.models[itemKey]
			if entry and entry.instance and MM2VisualParserFirstPart(entry.instance) then
				print(("[mm2run/fake-wear] loaded exact %s model %s"):format(
					tostring(itemKey), tostring(modelId)))
				if MM2VisualParser.snapshots[itemKey] then
					for _, object in ipairs(objects) do pcall(function() object:Destroy() end) end
				else
					for _, object in ipairs(objects) do table.insert(MM2VisualParser.externalObjects, object) end
				end
				return entry.instance
			end
			for _, object in ipairs(objects) do pcall(function() object:Destroy() end) end
			print(("[mm2run/fake-wear] model %s has no usable 3D parts for %s"):format(
				tostring(modelId), tostring(itemKey)))
		else
			print(("[mm2run/fake-wear] couldn't load exact model %s for %s"):format(
				tostring(modelId), tostring(itemKey)))
		end
	end

	-- One public pack can cover many older Godlies.  Nothing from the pack is
	-- parented or executed: only a matching renderable descendant is cloned into
	-- the local template cache, and all source objects are destroyed afterwards.
	for _, packId in ipairs(ExternalFakeWearPackIds) do
		local ok, objects = pcall(function()
			return game:GetObjects("rbxassetid://" .. tostring(packId))
		end)
		if ok and type(objects) == "table" then
			for _, object in ipairs(objects) do
				if MM2VisualParser.FindKeyForInstance(object) == itemKey then
					MM2VisualParserRecord(itemKey, object, "Creator Store MM2 pack " .. tostring(packId))
				end
				if not (MM2VisualParser.models[itemKey] and MM2VisualParser.models[itemKey].instance) then
					for _, desc in ipairs(object:GetDescendants()) do
						if MM2VisualParser.FindKeyForInstance(desc) == itemKey then
							MM2VisualParserRecord(itemKey, desc, "Creator Store MM2 pack " .. tostring(packId))
							if MM2VisualParser.models[itemKey] and MM2VisualParser.models[itemKey].instance then break end
						end
					end
				end
			end
			local entry = MM2VisualParser.models[itemKey]
			if entry and entry.instance and MM2VisualParserFirstPart(entry.instance) then
				if MM2VisualParser.snapshots[itemKey] then
					for _, object in ipairs(objects) do pcall(function() object:Destroy() end) end
				else
					for _, object in ipairs(objects) do table.insert(MM2VisualParser.externalObjects, object) end
				end
				print(("[mm2run/fake-wear] loaded %s from MM2 pack %s"):format(
					tostring(itemKey), tostring(packId)))
				return entry.instance
			end
			for _, object in ipairs(objects) do pcall(function() object:Destroy() end) end
		else
			print(("[mm2run/fake-wear] couldn't load MM2 pack %s"):format(tostring(packId)))
		end
	end

	return nil
end

-- Try only asset ids declared by MM2's live item row.  ModelID/AssetID are
-- preferred; ItemID remains a legacy fallback because older rows used it for
-- the insertable object while newer rows often use it only for an icon.
function MM2VisualParser.TryLoadItemAsset(itemKey)
	local attemptedAt = MM2VisualParser.assetAttempts[itemKey]
	if attemptedAt and (type(attemptedAt) ~= "number" or os.clock()-attemptedAt < 20) then return nil end
	MM2VisualParser.assetAttempts[itemKey] = os.clock()

	local data = WeaponData[itemKey]
	if type(data) ~= "table" then return nil end
	local assetIds, seenIds = {}, {}
	for _, field in ipairs({"ModelID", "ModelId", "AssetID", "AssetId", "ItemID"}) do
		local rawId = data[field]
		local itemId = rawId and tonumber(string.match(tostring(rawId), "%d+")) or nil
		if itemId and itemId > 0 and not seenIds[itemId] then
			seenIds[itemId] = true
			table.insert(assetIds, itemId)
		end
	end
	if #assetIds == 0 then return nil end

	for _, itemId in ipairs(assetIds) do
		local ok, objects = pcall(function()
			return game:GetObjects("rbxassetid://" .. tostring(itemId))
		end)
		if ok and type(objects) == "table" then
			local loadedClasses = {}
			for _, object in ipairs(objects) do
				table.insert(loadedClasses, object.ClassName)
				if MM2VisualParserFirstPart(object) then
					MM2VisualParserRecord(itemKey, object, "MM2-declared asset " .. tostring(itemId))
					local entry = MM2VisualParser.models[itemKey]
					if entry and entry.instance then
						print(("[mm2run/mm2-parse] loaded %s from MM2 asset %s as %s"):format(
							tostring(itemKey), tostring(itemId), entry.instance.ClassName))
						return entry.instance
					end
				end
			end
			print(("[mm2run/mm2-parse] asset %s for %s has no 3D model (%s)"):format(
				tostring(itemId), tostring(itemKey), table.concat(loadedClasses, ", ")))
		else
			print(("[mm2run/mm2-parse] couldn't load MM2 asset %s for %s"):format(
				tostring(itemId), tostring(itemKey)))
		end
	end
	return nil
end

local function MM2VisualParserFindDataField(root, wanted, depth, seen)
	if type(root) ~= "table" or depth > 4 then return nil end
	seen = seen or {}
	if seen[root] then return nil end
	seen[root] = true
	for field, value in pairs(root) do
		if wanted[string.lower(tostring(field))] and value ~= nil then return value end
	end
	for _, value in pairs(root) do
		if type(value) == "table" then
			local found = MM2VisualParserFindDataField(value, wanted, depth + 1, seen)
			if found ~= nil then return found end
		end
	end
	return nil
end

local function MM2VisualParserAssetUri(value)
	if value == nil then return nil end
	local id = string.match(tostring(value), "%d+")
	return id and ("rbxassetid://" .. id) or nil
end

-- Some MM2 builds expose the original MeshId/TextureId directly instead of a
-- parent model.  Reconstructing that declared mesh is still the real skin; no
-- replacement geometry and no server request are involved.
function MM2VisualParser.TryCreateFromWeaponData(itemKey)
	local attemptedAt = MM2VisualParser.dataMeshAttempts[itemKey]
	if attemptedAt and (type(attemptedAt) ~= "number" or os.clock()-attemptedAt < 20) then return nil end
	MM2VisualParser.dataMeshAttempts[itemKey] = os.clock()
	local data = WeaponData[itemKey]
	if type(data) ~= "table" then return nil end

	local meshValue = MM2VisualParserFindDataField(data, {
		meshid = true, mesh_id = true, meshassetid = true, mesh = true,
	}, 1)
	local meshUri = MM2VisualParserAssetUri(meshValue)
	if not meshUri then return nil end
	local textureValue = MM2VisualParserFindDataField(data, {
		textureid = true, texture_id = true, textureassetid = true, texture = true,
	}, 1)
	local scaleValue = MM2VisualParserFindDataField(data, {
		meshscale = true, mesh_scale = true, scale = true,
	}, 1)

	if Runtime.RepairTarget(itemKey) and scaleValue == nil then return nil end
	local model = Instance.new("Model")
	model.Name = tostring(itemKey)
	local handle = Instance.new("Part")
	handle.Name = "Handle"
	handle.Size = Vector3.new(1, 1, 1)
	handle.Anchored = true
	handle.CanCollide = false
	handle.CanTouch = false
	handle.CanQuery = false
	handle.Parent = model
	model.PrimaryPart = handle
	local mesh = Instance.new("SpecialMesh")
	mesh.MeshType = Enum.MeshType.FileMesh
	local ok = pcall(function()
		mesh.MeshId = meshUri
		local textureUri = MM2VisualParserAssetUri(textureValue)
		if textureUri then mesh.TextureId = textureUri end
		if typeof(scaleValue) == "Vector3" then
			mesh.Scale = scaleValue
		elseif tonumber(scaleValue) then
			local scalar = tonumber(scaleValue)
			mesh.Scale = Vector3.new(scalar, scalar, scalar)
		end
	end)
	if not ok then
		model:Destroy()
		return nil
	end
	mesh.Parent = handle
	MM2VisualParserRecord(itemKey, model, "MM2 WeaponData MeshId")
	model:Destroy()
	local entry = MM2VisualParser.models[itemKey]
	return entry and entry.instance or nil
end

local MM2RendererFactoryNames = {
	"GetWeaponModel", "GetItemModel", "CreateWeaponModel", "CreateItemModel",
	"CreateWeapon", "CreateItem", "BuildWeapon", "BuildItem", "LoadWeapon",
	"LoadItem", "GetModel", "GetWeapon",
}

local function MM2VisualParserRecordFactoryResult(itemKey, value, source)
	if typeof(value) == "Instance" then
		MM2VisualParserRecord(itemKey, value, source)
		return MM2VisualParser.models[itemKey] and MM2VisualParser.models[itemKey].instance
	end
	if type(value) == "table" then
		for _, field in ipairs({"Model", "model", "Asset", "asset", "Instance", "instance"}) do
			local candidate = rawget(value, field)
			if typeof(candidate) == "Instance" then
				MM2VisualParserRecord(itemKey, candidate, source .. "." .. field)
				return MM2VisualParser.models[itemKey] and MM2VisualParser.models[itemKey].instance
			end
		end
	end
	return nil
end

-- Weapon models which are absent from the instance tree can still be created
-- by an already-loaded client renderer.  Only cached ModuleScripts are used;
-- no server remotes are fired by this probe.
function MM2VisualParser.TryCreateFromLoadedRenderer(itemKey)
	if not getloadedmodules then return nil end
	if MM2VisualParser.rendererAttempts[itemKey] then return nil end
	MM2VisualParser.rendererAttempts[itemKey] = true
	local data = WeaponData[itemKey]
	local attempted = 0

	for _, module in ipairs(getloadedmodules()) do
		local moduleName = string.lower(module.Name)
		local relevant = string.find(moduleName, "item", 1, true)
			or string.find(moduleName, "weapon", 1, true)
			or string.find(moduleName, "knife", 1, true)
			or string.find(moduleName, "gun", 1, true)
		if relevant then
			local ok, exported = pcall(require, module)
			if ok and type(exported) == "table" then
				for _, factoryName in ipairs(MM2RendererFactoryNames) do
					local factory = rawget(exported, factoryName)
					if type(factory) == "function" then
						attempted = attempted + 1
						local success, result = pcall(factory, itemKey)
						local model = success and MM2VisualParserRecordFactoryResult(
							itemKey, result, module:GetFullName() .. "." .. factoryName) or nil
						if not model then
							success, result = pcall(factory, exported, itemKey)
							model = success and MM2VisualParserRecordFactoryResult(
								itemKey, result, module:GetFullName() .. "." .. factoryName .. "(self)") or nil
						end
						if not model and data then
							success, result = pcall(factory, data)
							model = success and MM2VisualParserRecordFactoryResult(
								itemKey, result, module:GetFullName() .. "." .. factoryName .. "(data)") or nil
						end
						if model then
							print(("[mm2run/mm2-parse] created %s via %s"):format(itemKey, module:GetFullName() .. "." .. factoryName))
							return model
						end
					end
				end
			end
		end
	end
	print(("[mm2run/mm2-parse] no local renderer factory created %s (%d factories checked)"):format(itemKey, attempted))
	return nil
end

_G.MM2VisualParser = MM2VisualParser
print("[Zoy0m/K1borg] Models load on demand")

-- Remove a previous wardrobe controller cleanly when the script is re-executed.
pcall(function()
	local previous = rawget(_G, "MM2FakeWearController")
	if type(previous) == "table" and type(previous.ClearAll) == "function" then
		previous.ClearAll()
	end
end)

-- One independent session is kept per player.  Knife/Gun choices, anchors,
-- hidden originals and retry timers are never shared between players.
local FakeWear = {
	sessions = {},
	connection = nil,
	maintenanceRunning = false,
	loopGeneration = 0,
	refreshInterval = 0.5,
	displayRoot = nil,
	displayRootCheckedAt = 0,
	staticRetryDone = {},
}

local FakeWearReplicatedStorage = game:GetService("ReplicatedStorage")
local FakeWearRunService = game:GetService("RunService")

local function FakeWearPlayerKey(player)
	if not player then return nil end
	local userId = nil
	pcall(function() userId = tonumber(player.UserId) end)
	if userId and userId ~= 0 then return "u" .. tostring(userId) end
	return "n" .. string.lower(tostring(player.Name or "unknown"))
end

local function FakeWearSafeName(value)
	local safe = string.gsub(tostring(value or "unknown"), "[^%w_]", "_")
	return safe ~= "" and safe or "unknown"
end

local function FakeWearNameMatches(value, wanted)
	if not value or not wanted then return false end
	return string.lower(tostring(value)) == string.lower(tostring(wanted))
end

local function FakeWearFirstPart(root)
	if not root then return nil end
	if root:IsA("BasePart") then return root end

	local handle = root:FindFirstChild("Handle", true)
	if handle and handle:IsA("BasePart") then return handle end
	if root:IsA("Model") and root.PrimaryPart then return root.PrimaryPart end

	for _, desc in ipairs(root:GetDescendants()) do
		if desc:IsA("BasePart") then return desc end
	end
	return nil
end

local function FakeWearWeaponCandidate(instance, weaponClass)
	if not instance then return false, nil end
	local itemKey = MM2VisualParser.FindKeyForInstance(instance)
	local itemData = itemKey and WeaponData[itemKey] or nil
	if type(itemData) == "table" and itemData.ItemType == weaponClass then
		return true, itemKey
	end
	local name = string.lower(tostring(instance.Name or ""))
	local className = string.lower(tostring(weaponClass or ""))
	return string.find(name, className, 1, true) ~= nil
		or string.find(name, "weapon", 1, true) ~= nil, nil
end

local function FakeWearIsLocalDisplay(instance)
	local cursor = instance
	for _ = 1, 10 do
		if not cursor or cursor == workspace then break end
		if string.find(cursor.Name, "__LocalFakeWear_", 1, true) == 1 then return true end
		cursor = cursor.Parent
	end
	return false
end

-- Only explicit ownership flags count as proof.  A selected radio skin, a
-- gamepass asset id or a generic Radio object exists even for non-owners.
local FakeWearRadioFlagNames = {
	hasradio = true,
	ownsradio = true,
	radioowned = true,
	hasradiogamepass = true,
	ownsradiogamepass = true,
	hasboombox = true,
	ownsboombox = true,
	boomboxowned = true,
}

local function FakeWearCompactName(value)
	return string.gsub(string.lower(tostring(value or "")), "[^%w]", "")
end

local function FakeWearLooksLikeRadioName(value)
	local compact = FakeWearCompactName(value)
	return string.find(compact, "radio", 1, true) ~= nil
		or string.find(compact, "boombox", 1, true) ~= nil
		or string.find(compact, "stereo", 1, true) ~= nil
end

local function FakeWearRadioBoolean(value)
	-- Three states: true, false, or nil (not evidence).  In particular,
	-- "Default", a model Instance and a nonzero asset id are NOT true.
	local kind = typeof(value)
	if kind == "boolean" then return value end
	if kind == "number" then
		if value == 1 then return true end
		if value == 0 then return false end
	elseif kind == "string" then
		local compact = FakeWearCompactName(value)
		if compact == "true" or compact == "1" then return true end
		if compact == "false" or compact == "0" then return false end
	end
	return nil
end

local function FakeWearVisiblePart(root)
	if typeof(root) ~= "Instance" then return nil end
	local function isVisible(part)
		if not part or not part:IsA("BasePart") then return false end
		local transparency, localTransparency = 0, 0
		pcall(function() transparency = tonumber(part.Transparency) or 0 end)
		pcall(function() localTransparency = tonumber(part.LocalTransparencyModifier) or 0 end)
		return transparency < 0.98 and localTransparency < 0.98
	end
	if root:IsA("BasePart") and isVisible(root) then return root end
	for _, desc in ipairs(root:GetDescendants()) do
		if desc:IsA("BasePart") and isVisible(desc) then return desc end
	end
	return nil
end

local function FakeWearReadRadioFlag(root, deep)
	if typeof(root) ~= "Instance" then return nil, nil end
	local knownFalse
	local function read(name, value, container)
		local compact = FakeWearCompactName(name)
		local recognized = FakeWearRadioFlagNames[compact]
		if not recognized and (compact == "radio" or compact == "boombox"
			or compact == "radiogamepass") then
			-- The ambiguous Radio key is accepted only as an actual boolean
			-- inside an explicitly named gamepass-ownership container.
			local parentName = FakeWearCompactName(container and container.Name)
			recognized = typeof(value) == "boolean"
				and (string.find(parentName, "gamepass", 1, true) ~= nil
					or parentName == "passes" or parentName == "ownedpasses")
		end
		if recognized then return FakeWearRadioBoolean(value) end
		return nil
	end
	local function attributes(container)
		local ok, values = pcall(function() return container:GetAttributes() end)
		if ok and type(values) == "table" then
			for name, value in pairs(values) do
				local state = read(name, value, container)
				local evidence = container:GetFullName() .. ".attribute(" .. tostring(name) .. ")"
				if state == true then return true, evidence end
				if state == false then knownFalse = knownFalse or evidence end
			end
		end
	end
	local found, evidence = attributes(root)
	if found then return true, evidence end
	for _, desc in ipairs(deep and root:GetDescendants() or root:GetChildren()) do
		if desc:IsA("ValueBase") and not desc:IsA("ObjectValue") then
			local ok, value = pcall(function() return desc.Value end)
			local state
			if ok then state = read(desc.Name, value, desc.Parent) end
			if state == true then return true, desc:GetFullName() end
			if state == false then knownFalse = knownFalse or desc:GetFullName() end
		elseif deep and (desc:IsA("Folder") or desc:IsA("Configuration")) then
			found, evidence = attributes(desc)
			if found then return true, evidence end
		end
	end
	if knownFalse then return false, knownFalse end
	return nil, nil
end

local function FakeWearDetectVisibleRadio(session)
	if not session then return false, "no session" end
	if session.radioOverride ~= nil then
		return session.radioOverride == true, "manual override"
	end
	local player = session.player
	local character = player and player.Character
	if not player or not character then return false, "no character" end

	local state, evidence = FakeWearReadRadioFlag(player, false)
	if state ~= nil then return state, evidence end
	for _, child in ipairs(player:GetChildren()) do
		local compact = FakeWearCompactName(child.Name)
		local likelyData = string.find(compact, "data", 1, true)
			or string.find(compact, "profile", 1, true)
			or string.find(compact, "gamepass", 1, true)
			or string.find(compact, "passes", 1, true)
		if likelyData and (child:IsA("Folder") or child:IsA("Configuration")) then
			state, evidence = FakeWearReadRadioFlag(child, true)
			if state ~= nil then return state, evidence end
		end
	end
	state, evidence = FakeWearReadRadioFlag(character, true)
	if state ~= nil then return state, evidence end

	-- No ownership flag: only an actually rendered radio attached near this
	-- character's back is evidence.  Do not infer ownership from Backpack,
	-- inventory/config entries, previews, or arbitrary ObjectValues.
	local torso = character:FindFirstChild("UpperTorso") or character:FindFirstChild("Torso")
		or character:FindFirstChild("LowerTorso") or character:FindFirstChild("HumanoidRootPart")
	if not torso or not torso:IsA("BasePart") then return false, "no ownership evidence" end
	local function renderedRadio(root)
		if typeof(root) ~= "Instance" or not root:IsDescendantOf(workspace)
			or FakeWearIsLocalDisplay(root) then return false end
		local part = FakeWearVisiblePart(root)
		if not part then return false end
		local relative = torso.CFrame:PointToObjectSpace(part.Position)
		return relative.Magnitude < 4 and relative.Z > torso.Size.Z * 0.15
			and math.abs(relative.X) < torso.Size.X * 0.65 + 0.3
	end
	for _, desc in ipairs(character:GetDescendants()) do
		local compact = FakeWearCompactName(desc.Name)
		if desc:IsA("ObjectValue") and (compact == "displayrefradio"
			or compact == "displayrefboombox" or compact == "radiodisplayref") then
			if renderedRadio(desc.Value) then return true, desc:GetFullName() .. " (rendered)" end
		elseif (desc:IsA("Accessory") or desc:IsA("Model") or desc:IsA("Tool"))
			and FakeWearLooksLikeRadioName(desc.Name) and renderedRadio(desc) then
			return true, desc:GetFullName() .. " (rendered)"
		end
	end
	return false, "no ownership or rendered-radio evidence"
end

local function FakeWearGetRadioState(session, force)
	if not session then return false, "no session" end
	local now = os.clock()
	if not force and session.hasRadio ~= nil
		and now - (session.radioCheckedAt or 0) < 2 then
		return session.hasRadio, session.radioEvidence
	end

	local previous = session.hasRadio
	local detected, evidence = FakeWearDetectVisibleRadio(session)
	session.radioCheckedAt = now
	session.hasRadio = detected == true
	session.radioEvidence = evidence
	if previous == nil or previous ~= session.hasRadio then
		session.radioRevision = (session.radioRevision or 0) + 1
		if session.worldWeapons then session.worldWeapons.Knife = nil end
		if session.worldSearchAt then session.worldSearchAt["Knife:displays"] = nil end
		if previous ~= nil or session.hasRadio then
			print(("[mm2run/fake-wear/radio] %s radio=%s (%s)"):format(
				tostring(session.targetName), tostring(session.hasRadio), tostring(evidence)))
		end
	end
	return session.hasRadio, session.radioEvidence
end

-- Holstered knives have two explicit mounts, never an interpolated left/back
-- point inside the torso.  Negative X is the avatar's left; positive Z is back.
local function FakeWearNativeKnifeRotation(session, torso, side, candidate, source)
	local character = session and session.player and session.player.Character
	if not character or not candidate or not candidate.Parent
		or FakeWearIsLocalDisplay(candidate) then return nil end
	-- A proximity match in WeaponDisplays can belong to somebody else.
	-- Only an exact DisplayRef or this character's own model is authoritative.
	if source ~= "display-ref" and not candidate:IsDescendantOf(character) then return nil end
	local part = (candidate:IsA("Model") and candidate.PrimaryPart) or FakeWearFirstPart(candidate)
	if not part then return nil end
	local relative = torso.CFrame:ToObjectSpace(part.CFrame)
	local position, up = relative.Position, relative.UpVector
	if position.Magnitude > 4.5 then return nil end
	-- Reject upright/transitional poses and mounts on the wrong surface.
	-- Otherwise reuse the game's real diagonal, instead of inventing a new one.
	if up.Y > -0.15 or up.Y < -0.93 then return nil end
	if side then
		if position.X > -torso.Size.X * 0.3 or math.abs(position.Z) > torso.Size.Z + 0.6
			or math.abs(up.X) > 0.35 or math.abs(up.Z) < 0.25 then return nil end
	else
		if position.Z < torso.Size.Z * 0.2 or math.abs(position.X) > torso.Size.X * 0.6
			or math.abs(up.Z) > 0.35 or math.abs(up.X) < 0.25 then return nil end
	end
	return relative - position
end

local function FakeWearKnifeBodyAnchor(session, candidate, source)
	local player = session and session.player
	local character = player and player.Character
	if not character then return nil end
	local hasRadio = FakeWearGetRadioState(session)
	local names = hasRadio
		and {"LowerTorso", "Torso", "UpperTorso", "HumanoidRootPart"}
		or {"UpperTorso", "Torso", "LowerTorso", "HumanoidRootPart"}
	local torso
	for _, name in ipairs(names) do
		local part = character:FindFirstChild(name)
		if part and part:IsA("BasePart") then torso = part break end
	end
	if not torso then return nil end

	local size = torso.Size
	local gap = 0.12
	local revision = tostring(session.radioRevision or 0)
	if hasRadio then
		local halfWidth = size.X * 0.5
		local upper = character:FindFirstChild("UpperTorso")
		if upper and upper:IsA("BasePart") then
			halfWidth = math.max(halfWidth, upper.Size.X * 0.5)
		end
		local y = -math.min(0.6, size.Y * 0.32)
		local hip = torso:FindFirstChild("LeftHipRigAttachment")
		if hip and hip:IsA("Attachment") then
			-- A hip attachment is inside the pelvis on many R15 bodies.  Only
			-- reuse its height, NOT its inset X/Z coordinates.
			y = hip.Position.Y - 0.32
		elseif torso.Name == "UpperTorso" then
			y = -(size.Y * 0.5 + 0.2)
		end
		local native = FakeWearNativeKnifeRotation(session, torso, true, candidate, source)
		-- In the MM2 skin frame +Y points toward the blade.  The old -10-degree
		-- roll left the blade UP and the handle DOWN (the reported screenshot).
		-- 125 degrees points the blade diagonally DOWN and BACK at the left hip,
		-- with the handle up/front, like the normal Christmas-tree knife mount.
		local rotation = native or CFrame.Angles(0, math.rad(90), math.rad(125))
		local offset = CFrame.new(-halfWidth - gap, y, 0) * rotation
		return torso, true, offset,
			"body:knife-side:" .. revision .. (native and ":native" or ":fallback"), nil
	end

	local y, backZ = 0, size.Z * 0.5
	local back = torso:FindFirstChild("BodyBackAttachment")
	if back and back:IsA("Attachment") then
		y = back.Position.Y
		backZ = math.max(backZ, back.Position.Z)
	end
	-- A trusted live back display is followed directly by the resolver below.
	-- This is ONLY the no-display fallback: blade up/left, handle down/right,
	-- like the original back knife, rather than the inverted side-holster pose.
	local offset = CFrame.new(0, y, backZ + 0.035) * CFrame.Angles(0, 0, math.rad(45))
	return torso, true, offset, "body:knife-back:" .. revision .. ":fallback", nil
end

local function FakeWearKnifeInHand(session, candidate)
	local character = session and session.player and session.player.Character
	if not character or not candidate then return false end
	local cursor = candidate
	while cursor and cursor ~= character and cursor ~= workspace do
		if cursor:IsA("Tool") and cursor.Parent == character then return true end
		cursor = cursor.Parent
	end

	-- Some renderers use a Model welded to the hand instead of a Tool.
	local function belongs(part)
		return part and (part == candidate or part:IsDescendantOf(candidate))
	end
	local function isGrip(joint, hand)
		if not (joint:IsA("JointInstance") or joint:IsA("WeldConstraint")) then return false end
		return (joint.Part0 == hand and belongs(joint.Part1))
			or (joint.Part1 == hand and belongs(joint.Part0))
	end
	for _, name in ipairs({"RightHand", "Right Arm", "RightLowerArm", "RightUpperArm"}) do
		local hand = character:FindFirstChild(name)
		if hand and hand:IsA("BasePart") then
			for _, joint in ipairs(hand:GetDescendants()) do
				if isGrip(joint, hand) then return true end
			end
			for _, joint in ipairs(candidate:GetDescendants()) do
				if isGrip(joint, hand) then return true end
			end
		end
	end
	return false
end

local function FakeWearNativeBackKnifeAnchor(session, candidate, source)
	local character = session and session.player and session.player.Character
	if not character or not candidate or not candidate.Parent
		or FakeWearIsLocalDisplay(candidate) then return nil end
	-- Never borrow another player's nearby WeaponDisplays pose.
	if source ~= "display-ref" and not candidate:IsDescendantOf(character) then return nil end
	local part = (candidate:IsA("Model") and candidate.PrimaryPart) or FakeWearFirstPart(candidate)
	if not part or not part:IsDescendantOf(workspace) then return nil end
	local torso = character:FindFirstChild("UpperTorso") or character:FindFirstChild("Torso")
		or character:FindFirstChild("LowerTorso") or character:FindFirstChild("HumanoidRootPart")
	if not torso or not torso:IsA("BasePart") then return nil end
	if (part.Position - torso.Position).Magnitude > 4.5 then return nil end
	-- Trust the original renderer's FULL frame.  Do not reject a blade-up
	-- original, strip its translation, or infer orientation from UpVector.
	-- Following this part each render frame also preserves the live animation.
	return part
end

-- v11: a gun's origin is NOT its belt mount.  The supplied native scan uses
-- LowerTorso.GunBelt == GunDisplay.CustomAttachment/Attachment in world space.
-- Different skins have different attachment translations AND rotations.
-- Thus: skinRootWorld = beltWorld * skinRootToMount:Inverse().
local FakeWearGun = {}

function FakeWearGun.Root(model)
	if not model then return nil end
	if model:IsA("BasePart") then return model end
	if model:IsA("Model") and model.PrimaryPart then return model.PrimaryPart end
	local display = model:FindFirstChild("GunDisplay")
	if display and display:IsA("BasePart") then return display end
	return FakeWearFirstPart(model)
end

