		{texture = 6120563948, size = Vector3.new(0.443201, 1.92998, 1.02381)},
	},
	["95356090"] = {
		{texture = 2674981863, size = Vector3.new(0.51, 1.180002, 1.349997), scale = Vector3.new(1.8, 1.8, 1.8), offset = Vector3.new(0, 0, 0)},
		{texture = 4535479829, size = Vector3.new(0.51, 1.180002, 1.349997), scale = Vector3.new(1.8, 1.8, 1.8), offset = Vector3.new(0, 0, 0)},
	},
	["6125843704"] = {
		{texture = 6125843755, size = Vector3.new(0.751499, 1.799049, 1.175335)},
	},
	["8310911339"] = {
		{texture = 8293539377, size = Vector3.new(0.469, 2.539, 1.1515)},
		{texture = 8320249073, size = Vector3.new(0.469, 2.539, 1.151), scale = Vector3.new(1, 1, 1), offset = Vector3.new(0, 0, 0)},
	},
	["92656610"] = {
		{texture = 386269992, size = Vector3.new(0.2, 1, 1.9), scale = Vector3.new(0.4, 0.45, 0.5), offset = Vector3.new(0, 0, 0)},
	},
	["130099641"] = {
		{texture = 209727730, size = Vector3.new(0.38, 1.340001, 1.880002), scale = Vector3.new(0.5, 0.5, 0.5), offset = Vector3.new(0, 0, 0)},
	},
	["118269783"] = {
		{texture = 203858007, size = Vector3.new(0.2, 1.03, 1.83), scale = Vector3.new(0.3, 0.43, 0.4), offset = Vector3.new(0, 0, 0)},
	},
}

function FakeWearGun.SameVector(a, b)
	return a ~= nil and b ~= nil and math.abs(a.X - b.X) < 0.001
		and math.abs(a.Y - b.Y) < 0.001 and math.abs(a.Z - b.Z) < 0.001
end

function FakeWearGun.MountOffset(model, root)
	root = root or FakeWearGun.Root(model)
	if not root then return nil, "no-root" end
	local key = model:GetAttribute("MM2RealWeaponTemplate") or model:GetAttribute("MM2WeaponKey")
	local data = key and WeaponData[key]
	local beach = data and (data.ItemName == "Sands" or data.ItemName == "Beachy")
	if beach and not root:FindFirstChild("CustomAttachment") then return nil, "unverified-beach-mount" end
	-- Never choose Forward, Up, muzzle, particle or beam attachments.
	for _, name in ipairs({"CustomAttachment", "Attachment"}) do
		local attachment = root:FindFirstChild(name)
		if attachment and attachment:IsA("Attachment") then
			return attachment.CFrame, "template:" .. name
		end
	end
	for _, name in ipairs({"CustomAttachment", "Attachment"}) do
		local attachment = model:FindFirstChild(name, true)
		if attachment and attachment:IsA("Attachment")
			and attachment.Parent and attachment.Parent:IsA("BasePart") then
			return root.CFrame:ToObjectSpace(attachment.Parent.CFrame)
				* attachment.CFrame, "template:nested-" .. name
		end
	end
	local meshId, textureId
	if root:IsA("MeshPart") then meshId, textureId = root.MeshId, root.TextureID end
	local mesh = root:FindFirstChildOfClass("SpecialMesh")
	if mesh then meshId, textureId = mesh.MeshId, mesh.TextureId end
	local assetId = MM2StaticMeshAssetId(meshId)
	local texture = MM2StaticMeshAssetId(textureId)
	for _, appearance in ipairs(assetId and FakeWearGun.ScannedAppearances[tostring(assetId)] or {}) do
		local meshMatches = (mesh ~= nil) == (appearance.scale ~= nil)
		if meshMatches and mesh then
			meshMatches = FakeWearGun.SameVector(mesh.Scale, appearance.scale)
				and FakeWearGun.SameVector(mesh.Offset, appearance.offset)
		end
		if meshMatches and texture == appearance.texture
			and FakeWearGun.SameVector(root.Size, appearance.size) then
			return FakeWearGun.ScannedMounts[tostring(assetId)], "scan:exact-appearance"
		end
	end
	return nil, "missing-mount"
end

function FakeWearGun.Trusted(session, candidate, source)
	local character = session and session.player and session.player.Character
	if not character or not candidate or not candidate.Parent
		or FakeWearIsLocalDisplay(candidate) then return false end
	if candidate:IsDescendantOf(character) then return true end
	-- Recheck the actual reference even for a cached object: source text or
	-- proximity alone is not proof that this gun belongs to this player.
	local ref = character:FindFirstChild("DisplayRefGun", true)
	return ref ~= nil and ref:IsA("ObjectValue") and ref.Value == candidate
end

function FakeWearGun.BodyAnchor(session, candidate)
	local character = session and session.player and session.player.Character
	if not character then return nil end
	for _, name in ipairs({"LowerTorso", "Torso", "UpperTorso"}) do
		local torso = character:FindFirstChild(name)
		if torso and torso:IsA("BasePart") then
			local belt = torso:FindFirstChild("GunBelt")
			if belt and belt:IsA("Attachment") then
				return torso, true, belt.CFrame, "gun-belt", candidate
			end
		end
	end
	-- Older renderers can expose the owned gun but not the named body mount.
	-- Recover beltWorld from ITS attachment, not from its center.
	if candidate then
		local root = FakeWearGun.Root(candidate)
		local mount = FakeWearGun.MountOffset(candidate, root)
		if root and root:IsDescendantOf(workspace) and mount then
			return root, false, mount, "gun-belt-proxy", candidate
		end
	end
	-- Last resort only: outside the RIGHT hip, never on a left arm.  This
	-- heuristic is for absent native mounts, not an exact scanned-avatar pose.
	local torso = character:FindFirstChild("LowerTorso") or character:FindFirstChild("Torso")
		or character:FindFirstChild("UpperTorso") or character:FindFirstChild("HumanoidRootPart")
	if torso and torso:IsA("BasePart") then
		local halfWidth = torso.Size.X * 0.5
		local upper = character:FindFirstChild("UpperTorso")
		if upper and upper:IsA("BasePart") then halfWidth = math.max(halfWidth, upper.Size.X * 0.5) end
		local y = torso.Name == "LowerTorso" and -torso.Size.Y * 0.5 - 0.1
			or -torso.Size.Y * 0.35
		local belt = CFrame.new(halfWidth + 0.25, y, 0) * CFrame.Angles(math.rad(160), 0, 0)
		return torso, true, belt, "gun-belt-fallback", candidate
	end
	return nil
end

function FakeWearGun.PlacementOffset(mount, skinMount)
	return mount * skinMount:Inverse()
end

local function FakeWearResolveWeaponAnchor(session, weaponClass, candidate, source)
	if not candidate then return nil end
	if weaponClass == "Gun" then
		if not FakeWearGun.Trusted(session, candidate, source) then return FakeWearGun.BodyAnchor(session) end
		if FakeWearKnifeInHand(session, candidate) then
			-- Keep an actually drawn weapon in the hand, not at the belt.
			-- The supplied scan covers holsters only, so do not substitute a
			-- holster CustomAttachment for a Tool's hand grip.
			return FakeWearGun.Root(candidate), false, CFrame.new(), "gun-in-hand", candidate
		end
		return FakeWearGun.BodyAnchor(session, candidate)
	end
	if weaponClass == "Knife" and not FakeWearKnifeInHand(session, candidate) then
		if not FakeWearGetRadioState(session) and not Runtime.RepairTarget(session.skins and session.skins.Knife) then
			local nativePart = FakeWearNativeBackKnifeAnchor(session, candidate, source)
			if nativePart then
				-- No bounding-box push, recentering, extra roll or extra stand-off.
				return nativePart, false, CFrame.new(), "knife-native-back", candidate
			end
		end
		-- Retain the working radio-side behavior; use a body back mount only
		-- while the player's own original display is genuinely unavailable.
		local anchor, bodyAnchor, offset, mode = FakeWearKnifeBodyAnchor(session, candidate, source)
		if anchor then return anchor, bodyAnchor, offset, mode, candidate end
	end
	return candidate, false, CFrame.new(), source or "weapon", candidate
end

local function FakeWearBodyAnchor(session, weaponClass)
	local player = session and session.player
	local character = player and player.Character
	if not character then return nil end
	if weaponClass == "Knife" then
		return FakeWearKnifeBodyAnchor(session)
	end

	if weaponClass == "Gun" then return FakeWearGun.BodyAnchor(session) end
	return nil
end

local function FakeWearKnifeSkinAnchor(model)
	-- Static MM2 models have a canonical PrimaryPart.  A decorative child
	-- named Handle must not replace that origin when positioning a holster.
	if model:IsA("Model") and model.PrimaryPart then return model.PrimaryPart end
	return FakeWearFirstPart(model)
end

local function FakeWearKnifeBackPlacementOffset(model, skinAnchor, mount)
	-- Fallback only.  Seat the main blade face against the back.  The old
	-- whole-model minimum Z allowed guards, spikes and effect parts to push
	-- the ENTIRE knife away from the body, even with a correct diagonal.
	local main = skinAnchor
	if main.Transparency >= 0.98 then
		local bestArea = -1
		for _, part in ipairs(model:GetDescendants()) do
			if part:IsA("BasePart") and part.Transparency < 0.98 then
				local area = part.Size.Y * math.max(part.Size.X, part.Size.Z)
				if area > bestArea then main, bestArea = part, area end
			end
		end
	end
	local relative = skinAnchor.CFrame:ToObjectSpace(main.CFrame)
	local localRotation = relative - relative.Position
	-- MM2's blade length is along Y; X or Z can be the thin face normal.
	-- Lay the thin axis along the back normal instead of mounting edge-on.
	local thinX = main.Size.X < main.Size.Z
	local faceRotation = thinX and CFrame.Angles(0, math.rad(90), 0) or CFrame.new()
	local rotation = (mount - mount.Position) * faceRotation * localRotation:Inverse()
	local mesh = main:FindFirstChildOfClass("SpecialMesh")
	local meshOffset = mesh and mesh.Offset or Vector3.new()
	local center = rotation:PointToWorldSpace(relative:PointToWorldSpace(meshOffset))
	local halfThickness = (thinX and main.Size.X or main.Size.Z) * 0.5
	local position = mount.Position + Vector3.new(-center.X, -center.Y, halfThickness - center.Z)
	return CFrame.new(position) * rotation
end

local function FakeWearKnifePlacementOffset(model, skinAnchor, mount, mode)
	local side = string.find(mode or "", "body:knife-side:", 1, true) == 1
	local back = string.find(mode or "", "body:knife-back:", 1, true) == 1
	if back then return FakeWearKnifeBackPlacementOffset(model, skinAnchor, mount) end
	if not side then return mount end

	-- Measure the cloned parts in the mount's orientation once on attachment,
	-- not every frame.  Centering just Handle puts asymmetric godlies/scythes
	-- inside the torso.  These bounds also account for SpecialMesh offsets.
	local rotation = mount - mount.Position
	local minimum = Vector3.new(math.huge, math.huge, math.huge)
	local maximum = Vector3.new(-math.huge, -math.huge, -math.huge)
	local measured = false
	local function include(part)
		local relative = rotation * skinAnchor.CFrame:ToObjectSpace(part.CFrame)
		local half = part.Size * 0.5
		local mesh = part:FindFirstChildOfClass("SpecialMesh")
		local meshOffset = mesh and mesh.Offset or Vector3.new()
		for x = -1, 1, 2 do
			for y = -1, 1, 2 do
				for z = -1, 1, 2 do
					local point = relative:PointToWorldSpace(meshOffset
						+ Vector3.new(half.X * x, half.Y * y, half.Z * z))
					minimum = Vector3.new(math.min(minimum.X, point.X),
						math.min(minimum.Y, point.Y), math.min(minimum.Z, point.Z))
					maximum = Vector3.new(math.max(maximum.X, point.X),
						math.max(maximum.Y, point.Y), math.max(maximum.Z, point.Z))
				end
			end
		end
		measured = true
	end
	for _, part in ipairs(model:GetDescendants()) do
		if part:IsA("BasePart") and part.Transparency < 0.98 then include(part) end
	end
	if not measured then include(skinAnchor) end
	local center = (minimum + maximum) * 0.5
	local correction = Vector3.new(-maximum.X, -center.Y, -center.Z)
	-- Keep the v8 side placement unchanged.  Back/native mounts no longer
	-- pass through this whole-model displacement.
	return CFrame.new(mount.Position + correction) * rotation
end

local function FakeWearHiddenProperty(instance)
	if not instance then return nil end
	if instance:IsA("BasePart") then
		return "LocalTransparencyModifier", 1
	end
	if instance:IsA("Decal") or instance:IsA("Texture") then
		return "Transparency", 1
	end
	if instance:IsA("ParticleEmitter") or instance:IsA("Trail") or instance:IsA("Beam")
		or instance:IsA("Fire") or instance:IsA("Smoke") or instance:IsA("Sparkles")
		or instance:IsA("PointLight") or instance:IsA("SpotLight")
		or instance:IsA("SurfaceLight") or instance:IsA("Highlight") then
		return "Enabled", false
	end
	return nil
end

local function FakeWearHideObject(instance, hiddenObjects)
	local property, hiddenValue = FakeWearHiddenProperty(instance)
	if not property then return end
	local readOk, originalValue = pcall(function() return instance[property] end)
	if not readOk then return end
	table.insert(hiddenObjects, {
		instance = instance,
		property = property,
		originalValue = originalValue,
		hiddenValue = hiddenValue,
	})
	pcall(function() instance[property] = hiddenValue end)
end

local function FakeWearKeepOriginalHidden(records)
	for _, record in ipairs(records or {}) do
		local instance = record.instance or record.part
		if instance and instance.Parent then
			local property = record.property or "LocalTransparencyModifier"
			local hiddenValue = record.hiddenValue
			if hiddenValue == nil then hiddenValue = 1 end
			pcall(function() instance[property] = hiddenValue end)
		end
	end
end

local function FakeWearClearClass(session, weaponClass)
	if not session or not session.displays then return end
	local display = session.displays[weaponClass]
	if not display then return end

	if display.chromaConnection then
		pcall(function() display.chromaConnection:Disconnect() end)
	end
	for _, original in ipairs(display.hiddenObjects or display.hiddenParts or {}) do
		local instance = original.instance or original.part
		if instance and instance.Parent then
			local property = original.property or "LocalTransparencyModifier"
			local originalValue = original.originalValue
			if originalValue == nil then originalValue = original.transparency end
			pcall(function() instance[property] = originalValue end)
		end
	end

	pcall(function()
		if display.model then display.model:Destroy() end
	end)
	session.displays[weaponClass] = nil
end

local function FakeWearClearSession(session, remove)
	if not session then return end
	local classes = {}
	for weaponClass in pairs(session.displays or {}) do
		table.insert(classes, weaponClass)
	end
	for _, weaponClass in ipairs(classes) do
		FakeWearClearClass(session, weaponClass)
	end
	session.worldWeapons = {}
	session.worldSearchAt = {}
	session.lastTemplateTry = {}
	session.radioCheckedAt = 0
	session.hasRadio = nil
	session.radioEvidence = nil
	session.radioRevision = (session.radioRevision or 0) + 1
	session.lastRadioCorrectionWeapon = nil
	if remove and session.key then
		FakeWear.sessions[session.key] = nil
	end
end

local function FakeWearClearAll()
	local sessions = {}
	for _, session in pairs(FakeWear.sessions) do table.insert(sessions, session) end
	for _, session in ipairs(sessions) do FakeWearClearSession(session, true) end
	if FakeWear.connection then
		pcall(function() FakeWear.connection:Disconnect() end)
		FakeWear.connection = nil
	end
	FakeWear.maintenanceRunning = false
	FakeWear.loopGeneration = FakeWear.loopGeneration + 1
end

local function FakeWearGetDisplayRoot()
	if FakeWear.displayRoot and FakeWear.displayRoot.Parent then
		return FakeWear.displayRoot
	end
	local now = os.clock()
	if now - (FakeWear.displayRootCheckedAt or 0) < 1 then return nil end
	FakeWear.displayRootCheckedAt = now
	local root = workspace:FindFirstChild("WeaponDisplays")
	if not root then
		pcall(function() root = workspace:FindFirstChild("WeaponDisplays", true) end)
	end
	FakeWear.displayRoot = root
	return root
end

-- MM2 exposes the exact world-rendered knife/gun through DisplayRefKnife and
-- DisplayRefGun in many builds.  The cache belongs to this player only.
local function FakeWearFindDisplayRef(session, weaponClass)
	local player = session and session.player
	local character = player and player.Character
	if not character then return nil end
	local reference = character:FindFirstChild("DisplayRef" .. tostring(weaponClass), true)
	if reference and reference:IsA("ObjectValue") then
		local value = reference.Value
		if value and value.Parent and FakeWearFirstPart(value) and not FakeWearIsLocalDisplay(value) then
			session.worldWeapons[weaponClass] = value
			return value
		end
	end
	return nil
end

local function FakeWearFindExternalWeapon(session, weaponClass)
	local player = session and session.player
	local character = player and player.Character
	if not character then return nil end
	local cached = session.worldWeapons[weaponClass]
	if cached and cached.Parent and FakeWearFirstPart(cached) and not FakeWearIsLocalDisplay(cached) then
		return cached
	end

	local scanKey = weaponClass .. ":displays"
	if os.clock() - (session.worldSearchAt[scanKey] or 0) < 1 then return nil end
	session.worldSearchAt[scanKey] = os.clock()
	local rootPart = character:FindFirstChild("HumanoidRootPart")
		or character:FindFirstChild("UpperTorso")
		or character:FindFirstChild("Torso")
	if not rootPart or not rootPart:IsA("BasePart") then return nil end
	local displays = FakeWearGetDisplayRoot()
	if not displays then return nil end

	local closest, closestDistance = nil, 14
	local seenCandidates = {}
	for _, desc in ipairs(displays:GetDescendants()) do
		if (desc:IsA("Model") or desc:IsA("Tool") or desc:IsA("Accessory") or desc:IsA("BasePart"))
			and not FakeWearIsLocalDisplay(desc) then
			local isWeapon, itemKey = FakeWearWeaponCandidate(desc, weaponClass)
			if isWeapon then
				local candidate = itemKey and MM2VisualParserRenderableRoot(desc) or desc
				if candidate and not seenCandidates[candidate] then
					seenCandidates[candidate] = true
					local part = FakeWearFirstPart(candidate)
					if part then
						local distance = (part.Position - rootPart.Position).Magnitude
						if distance < closestDistance then
							closest, closestDistance = candidate, distance
						end
					end
				end
			end
		end
	end
	if closest then
		session.worldWeapons[weaponClass] = closest
		print(("[mm2run/fake-wear] %s uses %s display: %s (%.1f studs)"):format(
			tostring(session.targetName), weaponClass, closest:GetFullName(), closestDistance))
	end
	return closest
end

local function FakeWearFindEquippedWeapon(session, weaponClass)
	local player = session and session.player
	local character = player and player.Character
	if not character then return nil end

	if session.character ~= character then
		session.character = character
		session.worldWeapons = {}
		session.worldSearchAt = {}
		session.radioCheckedAt = 0
		session.hasRadio = nil
		session.radioEvidence = nil
		session.radioRevision = (session.radioRevision or 0) + 1
		session.lastRadioCorrectionWeapon = nil
	end
	FakeWearGetRadioState(session)

	-- Drawn tools take priority over stale holster refs for BOTH classes.
	if weaponClass == "Knife" or weaponClass == "Gun" then
		for _, child in ipairs(character:GetChildren()) do
			if child:IsA("Tool") and not FakeWearIsLocalDisplay(child)
				and FakeWearFirstPart(child) and FakeWearWeaponCandidate(child, weaponClass) then
				return FakeWearResolveWeaponAnchor(session, weaponClass, child, "equipped-tool")
			end
		end
	end

	local displayRef = FakeWearFindDisplayRef(session, weaponClass)
	if displayRef then
		return FakeWearResolveWeaponAnchor(session, weaponClass, displayRef, "display-ref")
	end

	-- No nearest-player gun lookup: it could hide/follow another player's
	-- display.  Prefer this character's own model, then its body mount.

	local exact = character:FindFirstChild(weaponClass, true)
	if exact and FakeWearFirstPart(exact) and not FakeWearIsLocalDisplay(exact) then
		return FakeWearResolveWeaponAnchor(session, weaponClass, exact, "character-exact")
	end

	for _, desc in ipairs(character:GetDescendants()) do
		if (desc:IsA("Tool") or desc:IsA("Model") or desc:IsA("Accessory"))
			and FakeWearFirstPart(desc) and not FakeWearIsLocalDisplay(desc) then
			local isWeapon, itemKey = FakeWearWeaponCandidate(desc, weaponClass)
			if isWeapon then
				local candidate = itemKey and MM2VisualParserRenderableRoot(desc) or desc
				return FakeWearResolveWeaponAnchor(session, weaponClass, candidate, "character-candidate")
			end
		end
	end

	local cached = session.worldWeapons[weaponClass]
	if cached and cached.Parent and FakeWearFirstPart(cached) and not FakeWearIsLocalDisplay(cached) then
		return FakeWearResolveWeaponAnchor(session, weaponClass, cached, "cached-display")
	end

	-- Keeps the selected skin visible through lobby/round/respawn transitions.
	-- Holstered knife: outside the left hip with a radio, centered on the back
	-- without one.  Never use an arm or a point inside the torso as a fallback.
	return FakeWearBodyAnchor(session, weaponClass)
end

local function FakeWearFindTemplate(skinKey)
	local parsedTemplate = MM2VisualParser.Get(skinKey)
	if parsedTemplate and (not Runtime.RepairTarget(skinKey) or Runtime.ValidWeaponGeometry(parsedTemplate)) then return parsedTemplate end
	if parsedTemplate then MM2VisualParser.models[skinKey] = nil end

	-- If the background database finished after an earlier failed attempt, allow
	-- exactly one new static-row resolution for this skin.
	if MM2StaticMeshState.loaded and not FakeWear.staticRetryDone[skinKey] then
		MM2VisualParser.staticMeshAttempts[skinKey] = nil
		FakeWear.staticRetryDone[skinKey] = true
	end

	if Runtime.RepairTarget(skinKey) then
		parsedTemplate = MM2VisualParser.TryLoadItemAsset(skinKey)
		if parsedTemplate then return parsedTemplate end
	end
	parsedTemplate = MM2VisualParser.TryCreateFromStaticMeshData(skinKey)
	if parsedTemplate then return parsedTemplate end
	parsedTemplate = MM2VisualParser.TryCreateFromWeaponData(skinKey)
	if parsedTemplate then return parsedTemplate end
	parsedTemplate = MM2VisualParser.TryLoadItemAsset(skinKey)
	if parsedTemplate then return parsedTemplate end
	parsedTemplate = MM2VisualParser.TryCreateFromLoadedRenderer(skinKey)
	if parsedTemplate then return parsedTemplate end
	parsedTemplate = MM2VisualParser.TryLoadExternalReplacement(skinKey)
	if parsedTemplate then return parsedTemplate end

	MM2VisualParser.fallbackAt = MM2VisualParser.fallbackAt or {}
	local lastScan = MM2VisualParser.fallbackAt[skinKey]
	if lastScan and os.clock() - lastScan < 30 then return nil end
	MM2VisualParser.fallbackAt[skinKey] = os.clock()
	local data = WeaponData[skinKey]
	local displayName = data and data.ItemName or skinKey
	local roots = {FakeWearReplicatedStorage, workspace, game:GetService("Lighting")}
	for _, root in ipairs(roots) do
		local scanned = 0
		for _, desc in ipairs(root:GetDescendants()) do
			scanned = scanned + 1
			if (desc:IsA("Model") or desc:IsA("Tool") or desc:IsA("Accessory")
				or desc:IsA("Folder") or desc:IsA("BasePart"))
				and not FakeWearIsLocalDisplay(desc)
				and (FakeWearNameMatches(desc.Name, skinKey) or FakeWearNameMatches(desc.Name, displayName))
				and FakeWearFirstPart(desc) then
				MM2VisualParserRecord(skinKey, desc, "exact-name fallback scan")
				return MM2VisualParser.Get(skinKey) or desc
			end
			if scanned % 100 == 0 then task.wait() end
		end
	end

	local nilTemplate = nil
	pcall(function()
		if not getnilinstances then return end
		local scanned = 0
		for _, instance in ipairs(getnilinstances()) do
			scanned = scanned + 1
			if (instance:IsA("Model") or instance:IsA("Tool") or instance:IsA("Accessory")
				or instance:IsA("Folder") or instance:IsA("BasePart"))
				and not FakeWearIsLocalDisplay(instance)
				and (FakeWearNameMatches(instance.Name, skinKey) or FakeWearNameMatches(instance.Name, displayName))
				and FakeWearFirstPart(instance) then
				MM2VisualParserRecord(skinKey, instance, "getnilinstances exact-name fallback")
				nilTemplate = MM2VisualParser.Get(skinKey) or instance
				return
			end
			if scanned % 300 == 0 then task.wait() end
		end
	end)
	return nilTemplate
end

function Runtime.AssetsReady(template)
	local state = Runtime.assets[template]
	if state and state.ready then return true end
	if state and (state.loading or os.clock() - state.at < 15) then return false end
	state = {loading = true, at = os.clock(), ready = false}
	Runtime.assets[template] = state
	task.spawn(function()
		local failures = {}
		local ok, err = MM2StaticMeshAwait(function()
			game:GetService("ContentProvider"):PreloadAsync({template}, function(assetId, status)
				if status ~= Enum.AssetFetchStatus.Success then
					table.insert(failures, tostring(assetId))
				end
			end)
		end, 15)
		state.loading = false
		state.ready = Runtime.alive and ok and #failures == 0
		state.at = os.clock()
		if not state.ready and Runtime.alive then
			warn("[hashima|Dc:pipirka0258] Asset preview deferred: " .. tostring(err or table.concat(failures, ", ")))
		end
	end)
	return false
end

local function FakeWearAttach(session, weaponClass, skinKey, weapon, bodyAnchor, anchorOffset, anchorMode, hideWeapon)
	local player = session and session.player
	if not player or player.Parent ~= Players then return false, "player left" end

	if not weapon then
		weapon, bodyAnchor, anchorOffset, anchorMode, hideWeapon = FakeWearFindEquippedWeapon(session, weaponClass)
	end
	if not weapon then return false, "character anchor is not available" end
	anchorOffset = anchorOffset or CFrame.new()

	local template = FakeWearFindTemplate(skinKey)
	if not template then Runtime.RepairIssue(skinKey,"No model available; original retained"); return false,"skin model is not loaded" end
	if Runtime.RepairTarget(skinKey) and not Runtime.ValidWeaponGeometry(template) then
		Runtime.RepairIssue(skinKey,"No valid geometry; original retained")
		return false,"model geometry missing"
	end
	if not Runtime.AssetsReady(template) then return false, "skin assets are loading or unavailable" end
	if not Runtime.alive or player.Parent ~= Players or not weapon.Parent or session.skins[weaponClass] ~= skinKey then return false, "stale preview" end

	local ok, clone = pcall(function() return template:Clone() end)
	if not ok or not clone then return false, "could not clone skin model" end
	if not clone:IsA("Model") then
		local wrapper = Instance.new("Model")
		clone.Parent = wrapper
		if weaponClass == "Gun" and clone:IsA("BasePart") then wrapper.PrimaryPart = clone end
		clone = wrapper
	end

	for _, desc in ipairs(clone:GetDescendants()) do
		if desc:IsA("Script") or desc:IsA("LocalScript") or desc:IsA("ModuleScript") then
			desc:Destroy()
		elseif desc:IsA("JointInstance") or desc:IsA("Constraint") then
			-- A clone of a live display can retain links to the REAL avatar.
			-- All clone parts are anchored and moved by PivotTo; no physics
			-- joints are needed, especially not an external RigidConstraint.
			desc:Destroy()
		elseif desc:IsA("BasePart") then
			desc.Anchored = true
			desc.CanCollide = false
			desc.CanTouch = false
			desc.CanQuery = false
		end
	end

	local weaponAnchor = FakeWearFirstPart(weapon)
	local useKnifeRoot = weaponClass == "Knife"
		and (bodyAnchor == true or anchorMode == "knife-native-back")
	local skinAnchor = weaponClass == "Gun" and FakeWearGun.Root(clone)
		or (useKnifeRoot and FakeWearKnifeSkinAnchor(clone) or FakeWearFirstPart(clone))
	if not weaponAnchor or not skinAnchor then
		clone:Destroy()
		return false, "skin has no visible part"
	end

	local baseAnchorOffset = anchorOffset
	local needsBodyClearance = Runtime.RepairTarget(skinKey) and bodyAnchor == true
	local gunSkinMount, gunMountSource
	if weaponClass == "Gun" and anchorMode ~= "gun-in-hand" then
		gunSkinMount, gunMountSource = FakeWearGun.MountOffset(clone, skinAnchor)
		if not gunSkinMount then
			-- Unknown external assets cannot be calibrated from a different
			-- skin.  Keep a visible fallback but do not call it an exact mount.
			gunSkinMount = CFrame.new()
			warn("[mm2run/fake-wear/gun] " .. tostring(skinKey)
				.. " has no mount data; using unverified default belt alignment")
		end
		anchorOffset = FakeWearGun.PlacementOffset(baseAnchorOffset, gunSkinMount)
	end
	if weaponClass == "Knife" and bodyAnchor == true then
		anchorOffset = FakeWearKnifePlacementOffset(clone, skinAnchor, baseAnchorOffset, anchorMode)
	end

	if needsBodyClearance then
		anchorOffset = Runtime.ClearBody(clone, skinAnchor, anchorOffset, weaponAnchor, anchorMode or "")
	end
	if not Runtime.alive or player.Parent ~= Players or not weaponAnchor.Parent
		or session.skins[weaponClass] ~= skinKey then clone:Destroy(); return false,"stale preview" end
	-- Restore the previous original before recording the new transparency state.
	-- Otherwise a radio/back anchor switch could remember the already-hidden
	-- value as the original one and leave the real weapon invisible on cleanup.
	if session.displays[weaponClass] then FakeWearClearClass(session, weaponClass) end

	local hiddenObjects = {}
	if hideWeapon and hideWeapon.Parent then
		FakeWearHideObject(hideWeapon, hiddenObjects)
		for _, desc in ipairs(hideWeapon:GetDescendants()) do
			FakeWearHideObject(desc, hiddenObjects)
		end
	end

	clone.Name = "__LocalFakeWear_" .. FakeWearSafeName(session.key) .. "_" .. weaponClass
	clone.Parent = workspace
	local pivotToAnchor = clone:GetPivot():ToObjectSpace(skinAnchor.CFrame)
	local display = {
		model = clone,
		weapon = weapon,
		weaponAnchor = weaponAnchor,
		pivotToAnchor = pivotToAnchor,
		skinAnchor = skinAnchor,
		baseAnchorOffset = baseAnchorOffset,
		anchorOffset = anchorOffset,
		gunSkinMount = gunSkinMount,
		gunMountSource = gunMountSource,
		bodyAnchor = bodyAnchor == true,
		anchorMode = anchorMode or "unknown",
		hideWeapon = hideWeapon,
		hiddenObjects = hiddenObjects,
		chromaConnection = nil,
		skinKey = skinKey,
		template = template,
		clearanceBase = baseAnchorOffset,
		clearanceSize = weaponAnchor.Size,
		clearanceMode = anchorMode,
		pivotToAnchorInverse = pivotToAnchor:Inverse(),
	}
	session.displays[weaponClass] = display

	pcall(function()
		clone:PivotTo(weaponAnchor.CFrame * anchorOffset * pivotToAnchor:Inverse())
	end)
	pcall(function()
		display.chromaConnection = MM2StaticMeshStartChroma(clone, skinKey)
	end)
	print(("[mm2run/fake-wear] attached %s to %s | class=%s | mode=%s | anchor=%s | hidden=%s | template=%s"):format(
		tostring(skinKey), tostring(player.Name), tostring(weaponClass), tostring(anchorMode),
		tostring(weapon:GetFullName()), tostring(hideWeapon and hideWeapon:GetFullName() or "none"),
		tostring(template:GetFullName())))
	return true
end

local function FakeWearRefreshImpl(session)
	if not session or not session.player or session.player.Parent ~= Players then return end

	local obsolete = {}
	for weaponClass in pairs(session.displays or {}) do
		if not session.skins[weaponClass] then table.insert(obsolete, weaponClass) end
	end
	for _, weaponClass in ipairs(obsolete) do FakeWearClearClass(session, weaponClass) end

	for weaponClass, skinKey in pairs(session.skins or {}) do
		local display = session.displays[weaponClass]
		local currentWeapon, currentBodyAnchor, currentOffset, currentAnchorMode, currentHideWeapon =
			FakeWearFindEquippedWeapon(session, weaponClass)
		local currentTemplate = MM2VisualParser.models[skinKey]
		local invalid = display and (
			(currentTemplate and display.template and currentTemplate.instance ~= display.template)
			or 			not display.model or not display.model.Parent
			or not display.weaponAnchor or not display.weaponAnchor.Parent
			or display.weapon ~= currentWeapon
			or display.bodyAnchor ~= (currentBodyAnchor == true)
			or display.anchorMode ~= (currentAnchorMode or "unknown")
			or display.hideWeapon ~= currentHideWeapon
			or display.skinKey ~= skinKey
		)
		if invalid then
			FakeWearClearClass(session, weaponClass)
			display = nil
		elseif display and weaponClass == "Knife" and currentBodyAnchor == true
			and display.baseAnchorOffset ~= currentOffset then
			-- Adapt to live avatar resizing without recreating the skin.
			display.baseAnchorOffset = currentOffset
			display.anchorOffset = FakeWearKnifePlacementOffset(display.model,
				display.skinAnchor, currentOffset, currentAnchorMode)
		elseif display and weaponClass == "Gun" and display.gunSkinMount
			and display.baseAnchorOffset ~= currentOffset then
			-- Follow live GunBelt resizing/offset changes without recloning.
			display.baseAnchorOffset = currentOffset
			display.anchorOffset = FakeWearGun.PlacementOffset(currentOffset, display.gunSkinMount)
		end

		if display and Runtime.RepairTarget(skinKey) and currentBodyAnchor == true
			and (display.clearanceBase ~= currentOffset or display.clearanceSize ~= display.weaponAnchor.Size
				or display.clearanceMode ~= currentAnchorMode) then
			local offset = currentOffset or CFrame.new()
			if weaponClass == "Gun" then
				offset = FakeWearGun.PlacementOffset(offset, display.gunSkinMount or CFrame.new())
			else
				offset = FakeWearKnifePlacementOffset(display.model, display.skinAnchor, offset, currentAnchorMode)
			end
			display.anchorOffset = Runtime.ClearBody(display.model, display.skinAnchor, offset,
				display.weaponAnchor, currentAnchorMode or "")
			display.clearanceBase = currentOffset
			display.clearanceSize = display.weaponAnchor.Size
			display.clearanceMode = currentAnchorMode
		end
		if not display and currentWeapon then
			local lastTry = session.lastTemplateTry[weaponClass] or 0
			if os.clock() - lastTry >= 3 then
				session.lastTemplateTry[weaponClass] = os.clock()
				FakeWearAttach(session, weaponClass, skinKey, currentWeapon, currentBodyAnchor, currentOffset,
					currentAnchorMode, currentHideWeapon)
			end
		end
	end
end

local function FakeWearRefresh(session)
	if not Runtime.alive or not session or session.refreshing then return end
	session.refreshing = true
	local ok, err = pcall(FakeWearRefreshImpl, session)
	session.refreshing = false
	if not ok then warn("[Zoy0m/K1borg] Preview refresh: " .. tostring(err)) end
end

local function FakeWearRenderStep()
	local now = os.clock()
	if now - (FakeWear.lastRenderAt or 0) < 1/60 then return end
	FakeWear.lastRenderAt = now
	for _, session in pairs(FakeWear.sessions) do
		for _, display in pairs(session.displays or {}) do
			if display.model and display.model.Parent and display.weaponAnchor and display.weaponAnchor.Parent then
				pcall(function()
					local anchor = display.weaponAnchor.CFrame
					local offset = display.anchorOffset or CFrame.new()
					if anchor ~= display.lastAnchor or offset ~= display.lastOffset then
						display.model:PivotTo(anchor * offset * display.pivotToAnchorInverse)
						display.lastAnchor, display.lastOffset = anchor, offset
					end
					if now - (display.hiddenCheckedAt or 0) >= 0.5 then
						FakeWearKeepOriginalHidden(display.hiddenObjects or display.hiddenParts)
						display.hiddenCheckedAt = now
					end
				end)
			end
		end
	end
end

local function FakeWearStartLoops()
	if not Runtime.alive then return end
	if not FakeWear.connection then
		FakeWear.connection = FakeWearRunService.RenderStepped:Connect(FakeWearRenderStep)
	end
	if FakeWear.maintenanceRunning then return end
	FakeWear.maintenanceRunning = true
	FakeWear.loopGeneration = FakeWear.loopGeneration + 1
	local generation = FakeWear.loopGeneration
	task.spawn(function()
		while FakeWear.maintenanceRunning and FakeWear.loopGeneration == generation do
			local sessionKeys = {}
			for key in pairs(FakeWear.sessions) do table.insert(sessionKeys, key) end
			for _, key in ipairs(sessionKeys) do
				if not FakeWear.maintenanceRunning or FakeWear.loopGeneration ~= generation then break end
				local session = FakeWear.sessions[key]
				if session then
					if session.player and session.player.Parent == Players then
						local ok, err = pcall(FakeWearRefresh, session)
						if not ok then
							warn("[mm2run/fake-wear] refresh failed for "
								.. tostring(session.targetName) .. ": " .. tostring(err))
						end
					elseif next(session.displays or {}) then
						FakeWearClearSession(session, false)
					end
				end
				task.wait()
			end
			task.wait(FakeWear.refreshInterval)
		end
	end)
end

local function FakeWearCopySkins(skins)
	local copy = {}
	for weaponClass, skinKey in pairs(skins or {}) do copy[weaponClass] = skinKey end
	return copy
end

local function FakeWearSetSession(player, skins)
	if not Runtime.alive then return nil end
	local key = FakeWearPlayerKey(player)
	if not key then return nil end
	local session = FakeWear.sessions[key]
	if not session then
		session = {
			key = key,
			player = player,
			targetName = player.Name,
			userId = player.UserId,
			skins = {},
			displays = {},
			lastTemplateTry = {},
			worldWeapons = {},
			worldSearchAt = {},
			character = player.Character,
			radioOverride = nil,
			radioCheckedAt = 0,
			hasRadio = nil,
			radioEvidence = nil,
			radioRevision = 0,
			lastRadioCorrectionWeapon = nil,
		}
		FakeWear.sessions[key] = session
	end

	local oldSkins = session.skins or {}
	local toClear = {}
	for weaponClass in pairs(session.displays or {}) do
		if oldSkins[weaponClass] ~= skins[weaponClass] then
			table.insert(toClear, weaponClass)
		end
	end
	for _, weaponClass in ipairs(toClear) do FakeWearClearClass(session, weaponClass) end

	session.player = player
	session.targetName = player.Name
	session.userId = player.UserId
	session.skins = FakeWearCopySkins(skins)
	session.lastTemplateTry = {}
	session.worldWeapons = {}
	session.worldSearchAt = {}
	session.character = player.Character
	session.radioCheckedAt = 0
	session.hasRadio = nil
	session.radioEvidence = nil
	session.radioRevision = (session.radioRevision or 0) + 1
	session.lastRadioCorrectionWeapon = nil
	FakeWearStartLoops()
	FakeWearRefresh(session)
	return session
end

local function FakeWearParseMarketValue(value)
	if type(value) == "number" then return value end
	local cleaned = string.gsub(tostring(value or ""), "[,%s]", "")
	return tonumber(cleaned) or 0
end

local function FakeWearNormalizeValueName(value)
	local text = tostring(value or "")
	if type(normalizeWeaponName) == "function" then
		local ok, normalized = pcall(normalizeWeaponName, text)
		if ok and type(normalized) == "string" then return normalized end
	end
	text = string.lower(text)
	text = string.gsub(text, "^c%.%s*", "chroma ")
	text = string.gsub(text, "['\u{2019}\"]", "")
	text = string.gsub(text, "%s+", " ")
	text = string.gsub(text, "^%s+", "")
	text = string.gsub(text, "%s+$", "")
	return text
end

local function FakeWearValueCandidates(itemKey)
	local out, seen = {}, {}
	local function add(value)
		if value == nil then return end
		local valueText = tostring(value)
		if valueText == "" then return end
		local id = string.lower(valueText)
		if seen[id] then return end
		seen[id] = true
		table.insert(out, valueText)
	end

	local data = WeaponData[itemKey]
	add(itemKey)
	if type(data) == "table" then
		add(data.ItemName)
		add(data.Name)
		add(data.DisplayName)

		-- MM2 often stores Chromas under keys such as DarkbringerChroma while
		-- value APIs expose them as "Chroma Darkbringer" or "C. Darkbringer".
		-- Generate both aliases so a Chroma can never inherit the regular price.
		if data.Chroma == true then
			local function addChromaAliases(value)
				if value == nil then return end
				local base = tostring(value)
				base = string.gsub(base, "^%s+", "")
				base = string.gsub(base, "%s+$", "")
				base = string.gsub(base, "^[Cc][Hh][Rr][Oo][Mm][Aa][%s_%-]*", "")
				base = string.gsub(base, "[%s_%-]*[Cc][Hh][Rr][Oo][Mm][Aa]$", "")
				base = string.gsub(base, "^[Cc]%.%s*", "")
				if base ~= "" then
					add("Chroma " .. base)
					add("C. " .. base)
				end
			end
			addChromaAliases(itemKey)
			addChromaAliases(data.ItemName)
			addChromaAliases(data.Name)
			addChromaAliases(data.DisplayName)
		end
	end
	if itemKey == "Sorry" then add("Corrupt") end
	return out
end

local function FakeWearLookupMarketValue(itemKey)
	if type(Runtime.InventoryUnitValue) ~= "function" then return 0, "loading", tostring(itemKey) end
	local value, source, name = Runtime.InventoryUnitValue(itemKey)
	return value or 0, source, name or tostring(itemKey)
end

LookupMarketValueForWeapon = FakeWearLookupMarketValue

local FakeWearRarityRank = {
	Chroma = 1000, Unique = 900, Ancient = 800, Godly = 700,
	Classic = 600, Vintage = 550, Legendary = 500, Rare = 400,
	Uncommon = 300, Common = 200,
}

local function FakeWearWaitForValueCatalog(maxSeconds)
	if not Values or Values.cache or not Values.fetching then return end
	local deadline = os.clock() + (maxSeconds or 3)
	while Values and Values.fetching and not Values.cache and os.clock() < deadline do
		task.wait(0.05)
	end
end

-- Returns at most one knife and at most one gun.  When several items of the
-- same class were offered, the highest per-item market value wins.
local function GetLastFakeTradeSkins(partnerName)
	local bestByClass = {}
	for offerIndex, item in ipairs(LastFakeTradeOffers[partnerName] or {}) do
		if item.itemType == "Weapons" then
			local data = WeaponData[item.itemName]
			if type(data) == "table" and (data.ItemType == "Knife" or data.ItemType == "Gun") then
				local rarity = data.Chroma == true and "Chroma" or tostring(data.Rarity or "Common")
				local value, valueSource, matchedName = FakeWearLookupMarketValue(item.itemName)
				local candidate = {
					key = item.itemName,
					displayName = data.ItemName or matchedName or item.itemName,
					value = value,
					valueSource = valueSource,
					rarity = rarity,
					rarityRank = FakeWearRarityRank[rarity] or 0,
					offerIndex = offerIndex,
					amount = tonumber(item.amount) or 1,
				}
				local current = bestByClass[data.ItemType]
				local better = not current or candidate.value > current.value
				if current and candidate.value == current.value and candidate.value <= 0 then
					better = candidate.rarityRank > current.rarityRank
				end
				if better then bestByClass[data.ItemType] = candidate end
				print(("[mm2run/fake-wear/value] %s candidate %s = %s (%s)"):format(
					data.ItemType, tostring(candidate.displayName), FormatValue(candidate.value), candidate.valueSource))
			end
		end
	end

	local skins = {}
	for weaponClass, selected in pairs(bestByClass) do
		skins[weaponClass] = selected.key
		print(("[mm2run/fake-wear/value] selected %s for %s: %s = %s (%s)"):format(
			weaponClass, tostring(partnerName), tostring(selected.displayName),
			FormatValue(selected.value), tostring(selected.valueSource)))
	end
	return skins, bestByClass
end

local function FakeWearStoredTargetCount()
	local count = 0
	for _ in pairs(FakeWear.sessions) do count = count + 1 end
	return count
end

local function WearLastFakeTradeWeapons()
	local partnerName = LastTradePartner
	if not partnerName or partnerName == "" then
		return false, "Complete a local trade first"
	end

	local player = Players:FindFirstChild(partnerName)
	if not player then
		return false, "Player is not in this server"
	end

	-- Waiting here does not block rendering: the button invokes this function in
	-- task.spawn.  It only improves the chance that ties are resolved by the full
	-- value catalog instead of the built-in fallback table.
	FakeWearWaitForValueCatalog(3)
	local skins, selected = GetLastFakeTradeSkins(partnerName)
	if not next(skins) then
		return false, "No weapon in the last local trade"
	end

	-- Do not force MM2VisualParser.Build(true) here.  The full scan/database are
	-- warmed in the background, and only the one or two selected templates are
	-- built now.  Yield between them to avoid a long single frame.
	local unavailable = {}
	for _, weaponClass in ipairs({"Knife", "Gun"}) do
		local skinKey = skins[weaponClass]
		if skinKey then
			task.wait()
			if not FakeWearFindTemplate(skinKey) then
				table.insert(unavailable, weaponClass .. ": " .. tostring(skinKey))
			end
		end
	end

	local session = FakeWearSetSession(player, skins)
	if not session then return false, "Could not create preview session" end

	local names = {}
	for _, weaponClass in ipairs({"Knife", "Gun"}) do
		local pick = selected[weaponClass]
		if pick then
			local suffix = pick.value > 0 and (" [" .. FormatValue(pick.value) .. "]") or ""
			table.insert(names, weaponClass .. ": " .. tostring(pick.displayName) .. suffix)
		end
	end

	local missing = {}
	for _, weaponClass in ipairs({"Knife", "Gun"}) do
		if skins[weaponClass] and not session.displays[weaponClass] then
			table.insert(missing, weaponClass .. ": " .. tostring(skins[weaponClass]))
		end
	end
	local saved = FakeWearStoredTargetCount()
	if #missing > 0 then
		local reason = #unavailable > 0 and ("; loading model: " .. table.concat(unavailable, ", "))
			or ("; waiting for character: " .. table.concat(missing, ", "))
		return true, "Saved for " .. tostring(partnerName) .. " — " .. table.concat(names, ", ")
			.. reason .. " | saved players: " .. tostring(saved)
	end
	return true, "Preview on " .. tostring(partnerName) .. " — " .. table.concat(names, ", ")
		.. " | saved players: " .. tostring(saved)
end

-- A saved target survives round respawns and even a leave/rejoin in the same
-- running client.  Only that player's visual instances are temporarily cleared.
Runtime.Connect(Players.PlayerRemoving, function(player)
	local session = FakeWear.sessions[FakeWearPlayerKey(player)]
	if session then
		FakeWearClearSession(session, false)
		session.player = nil
		session.character = nil
		print("[mm2run/fake-wear] saved wardrobe for departed player " .. tostring(player.Name))
	end
end)

Runtime.Connect(Players.PlayerAdded, function(player)
	local session = FakeWear.sessions[FakeWearPlayerKey(player)]
	if session then
		session.player = player
		session.targetName = player.Name
		session.character = player.Character
		session.worldWeapons = {}
		session.worldSearchAt = {}
		session.lastTemplateTry = {}
		session.radioCheckedAt = 0
		session.hasRadio = nil
		session.radioEvidence = nil
		session.radioRevision = (session.radioRevision or 0) + 1
		session.lastRadioCorrectionWeapon = nil
		FakeWearStartLoops()
		print("[mm2run/fake-wear] restored saved wardrobe session for " .. tostring(player.Name))
	end
end)

_G.MM2FakeWearController = {
	Sessions = FakeWear.sessions,
	ClearAll = FakeWearClearAll,
	RefreshAll = function()
		for _, session in pairs(FakeWear.sessions) do
			if session.player and session.player.Parent == Players then
				task.spawn(function() FakeWearRefresh(session) end)
			end
		end
	end,
	-- enabled=true forces the left-side knife holster, false forces the back,
	-- and nil/"auto" returns to automatic radio detection.
	SetRadioSide = function(playerOrName, enabled)
		local player = typeof(playerOrName) == "Instance" and playerOrName
			or Players:FindFirstChild(tostring(playerOrName or ""))
		local key = player and FakeWearPlayerKey(player) or nil
		if not key then
			local wanted = string.lower(tostring(playerOrName or ""))
			for candidateKey, candidate in pairs(FakeWear.sessions) do
				if string.lower(tostring(candidate.targetName or "")) == wanted then
					key = candidateKey
					break
				end
			end
		end
		local session = key and FakeWear.sessions[key] or nil
		if not session then return false, "session not found" end
		if enabled == nil or string.lower(tostring(enabled)) == "auto" then
			session.radioOverride = nil
		elseif type(enabled) == "string" then
			local compact = FakeWearCompactName(enabled)
			session.radioOverride = not (compact == "false" or compact == "0" or compact == "off")
		else
			session.radioOverride = enabled == true
		end
		session.radioCheckedAt = 0
		session.hasRadio = nil
		session.radioEvidence = nil
		session.radioRevision = (session.radioRevision or 0) + 1
		session.worldWeapons.Knife = nil
		session.worldSearchAt["Knife:displays"] = nil
		session.lastRadioCorrectionWeapon = nil
		if session.player and session.player.Parent == Players then
			task.spawn(function() FakeWearRefresh(session) end)
		end
		return true, session.radioOverride
	end,
	RemovePlayer = function(playerOrName)
		local player = typeof(playerOrName) == "Instance" and playerOrName
			or Players:FindFirstChild(tostring(playerOrName or ""))
		local key = player and FakeWearPlayerKey(player) or nil
		if not key then
			local wanted = string.lower(tostring(playerOrName or ""))
			for candidateKey, session in pairs(FakeWear.sessions) do
				if string.lower(tostring(session.targetName or "")) == wanted then key = candidateKey break end
			end
		end
		local session = key and FakeWear.sessions[key] or nil
		if session then FakeWearClearSession(session, true) return true end
		return false
	end,
}

