local function _getLeaderboardContainer()
    local PlayerGui = Players.LocalPlayer:WaitForChild("PlayerGui")
    local MainGUI = PlayerGui:FindFirstChild("MainGUI")
    local Game = MainGUI and MainGUI:FindFirstChild("Game")
    local Leaderboard = Game and Game:FindFirstChild("Leaderboard")
    return Leaderboard and Leaderboard:FindFirstChild("Container")
