local function showFakeTrade(onAcceptCallback)
    local Container = _getLeaderboardContainer()
    local FakeTradeRequest = Container and Container:FindFirstChild("FakeTradeRequest")
    if not FakeTradeRequest or not FakeTradeRequest.Parent then
        pcall(setupFakeTrade)
        Container = _getLeaderboardContainer()
        FakeTradeRequest = Container and Container:FindFirstChild("FakeTradeRequest")
    end
    if FakeTradeRequest then
        getgenv().FakeTradeOnAccept = onAcceptCallback
        local usernameLabel = FakeTradeRequest:FindFirstChild("UsernameLabel")
        if usernameLabel then
            local chosenName = getgenv().FakeTradeChosenName
            if not chosenName or chosenName == "" then chosenName = "Unknown" end
            usernameLabel.Text = chosenName
        end
        FakeTradeRequest.Visible = false
        task.defer(function()
            if FakeTradeRequest and FakeTradeRequest.Parent then
                FakeTradeRequest.Visible = true
            end
        end)
    end
end

getgenv().TriggerFakeTrade = showFakeTrade

