TriggerWearFakeWeapon = function()
	if wearFakeWeaponBusy then
		print("[mm2run/fake-wear] already working")
		return false
	end
	wearFakeWeaponBusy = true
	wearFakeWeaponSerial = wearFakeWeaponSerial + 1
	local mySerial = wearFakeWeaponSerial
	if wearFakeWeaponButton and wearFakeWeaponButton.Parent then
		wearFakeWeaponButton.Active = false
		wearFakeWeaponButton.Text = "Loading preview..."
		wearFakeWeaponButton.BackgroundColor3 = Color3.fromRGB(125, 95, 35)
	end

	-- Selection, value lookup and any missing model build run outside the GUI
	-- callback.  Existing players keep their own independent sessions.
	task.spawn(function()
		local callOk, wearOk, message = pcall(WearLastFakeTradeWeapons)
		if not callOk then
			message = wearOk
			wearOk = false
		end
		message = tostring(message or "Unknown error")
		print("[mm2run/fake-wear] " .. message)

		wearFakeWeaponBusy = false
		if wearFakeWeaponButton and wearFakeWeaponButton.Parent then
			wearFakeWeaponButton.Active = true
			wearFakeWeaponButton.Text = wearOk and "Preview saved" or "Preview unavailable"
			wearFakeWeaponButton.BackgroundColor3 = wearOk
				and Color3.fromRGB(40, 145, 90) or Color3.fromRGB(165, 65, 65)
		end

		task.delay(3, function()
			if wearFakeWeaponSerial == mySerial and wearFakeWeaponButton and wearFakeWeaponButton.Parent then
				wearFakeWeaponButton.Text = "Wear preview"
				wearFakeWeaponButton.BackgroundColor3 = Color3.fromRGB(17, 62, 123)
			end
		end)
	end)
	return true
end

