PickRandomTradePartner = function()
	if #FakeTradePartners == 0 then return false end
	local chosen = FakeTradePartners[math.random(1, #FakeTradePartners)]
	if #FakeTradePartners > 1 then
		for _ = 1, 8 do
			if chosen ~= lastRandomPartner then break end
			chosen = FakeTradePartners[math.random(1, #FakeTradePartners)]
		end
	end
	lastRandomPartner = chosen
	TradeTable.Player2.Player = chosen
	PartnerUserBox.Text = chosen
	pcall(function() TheirOffer.Username.Text = "(" .. chosen .. ")" end)
	print("[mm2run/random] picked partner " .. chosen .. " from " .. tostring(#FakeTradePartners) .. " usernames")
	return true, chosen
end

local RandomPricedWeaponConfig = {
	minValue = 50,
	maxValue = 20000,
	smallMaxValue = 500,
}
local RandomPricedWeaponRarities = {
	Godly = true,
	Ancient = true,
	Unique = true,
	Chroma = true,
}
local RandomPricedWeaponPools = {
	regular = {},
	small = {},
	rebuilding = false,
	scheduled = false,
	pending = false,
	reason = "not built",
}

local function RandomPricedWeaponTradable(data)
	if type(data) ~= "table" then return false end
	if data.Tradable == false or data.CanTrade == false then return false end
	if data.Untradable == true or data.NonTradable == true then return false end
	if data.Locked == true then return false end
	return true
end

local function RebuildRandomPricedWeaponPools(reason)
	if RandomPricedWeaponPools.rebuilding then
		RandomPricedWeaponPools.pending = true
		return
	end
	RandomPricedWeaponPools.rebuilding = true
	task.spawn(function()
		repeat
			RandomPricedWeaponPools.pending = false
			local regular, small = {}, {}
			for index, entry in ipairs(WeaponCatalog) do
				local data = WeaponData[entry.key]
				local rarity = entry.chroma and "Chroma" or tostring(entry.rarity or (data and data.Rarity) or "")
				if RandomPricedWeaponRarities[rarity] and RandomPricedWeaponTradable(data)
					and type(LookupMarketValueForWeapon) == "function" then
					local value, source, matchedName = LookupMarketValueForWeapon(entry.key)
					value = tonumber(value) or 0
					if value >= RandomPricedWeaponConfig.minValue
						and value <= RandomPricedWeaponConfig.maxValue then
						local record = {
							key = entry.key,
							name = entry.name or matchedName or entry.key,
							value = value,
							source = source,
							rarity = rarity,
							type = entry.type,
						}
						table.insert(regular, record)
						if value <= RandomPricedWeaponConfig.smallMaxValue then
							table.insert(small, record)
						end
					end
				end
				if index % 40 == 0 then task.wait() end
			end
			table.sort(regular, function(a, b)
				if a.value ~= b.value then return a.value > b.value end
				return tostring(a.name) < tostring(b.name)
			end)
			table.sort(small, function(a, b)
				if a.value ~= b.value then return a.value > b.value end
				return tostring(a.name) < tostring(b.name)
			end)
			RandomPricedWeaponPools.regular = regular
			RandomPricedWeaponPools.small = small
			RandomPricedWeaponPools.reason = tostring(reason or "refresh")
			print(("[mm2run/random] pools ready: regular=%d [%s-%s], small=%d [%s-%s] (%s)"):format(
				#regular, FormatValue(RandomPricedWeaponConfig.minValue), FormatValue(RandomPricedWeaponConfig.maxValue),
				#small, FormatValue(RandomPricedWeaponConfig.minValue), FormatValue(RandomPricedWeaponConfig.smallMaxValue),
				RandomPricedWeaponPools.reason))
		until not RandomPricedWeaponPools.pending
		RandomPricedWeaponPools.rebuilding = false
	end)
end

ScheduleRandomGodlyPoolRebuild = function(reason)
	RandomPricedWeaponPools.pending = true
	if RandomPricedWeaponPools.rebuilding or RandomPricedWeaponPools.scheduled then return end
	RandomPricedWeaponPools.scheduled = true
	task.defer(function()
		task.wait(0.05)
		RandomPricedWeaponPools.scheduled = false
		RebuildRandomPricedWeaponPools(reason)
	end)
end

AddRandomPricedWeapon = function(mode)
	local isSmall = mode == "small"
	local pool = isSmall and RandomPricedWeaponPools.small or RandomPricedWeaponPools.regular
	if #pool == 0 then
		ScheduleRandomGodlyPoolRebuild("button requested refresh")
		print("[mm2run/random] value pool is still loading; press the button once more")
		return false
	end
	local picked = pool[math.random(1, #pool)]
	local ok = OfferItemAnotherPlayer(picked.key, "Weapons")
	local poolName = isSmall and "small" or "regular"
	if ok then
		print(("[mm2run/random] %s added %s [%s, %s, %s]"):format(
			poolName, tostring(picked.name), FormatValue(picked.value), tostring(picked.rarity), tostring(picked.source)))
	else
		print(("[mm2run/random] couldn't add %s (trade locked, full, or not started)"):format(tostring(picked.name)))
	end
	return ok, picked
end

AcceptTheirOfferAction = function()
	if not next(TradeTable["Player1"]["Offer"]) and not next(TradeTable["Player2"]["Offer"]) then
		return false
	end
	if v84 then return false end
	TheirOffer.Accepted.Visible = true
	TradeTable["Player2"]["Accepted"] = true
	AcceptTrade()
	return true
end

