local function harvestProfile(raw)
	if type(raw) ~= "table" or type(raw.Weapons) ~= "table"
		or type(raw.Weapons.Owned) ~= "table" then return nil end
	local byKey, out = {}, {}
	for index, owned in pairs(raw.Weapons.Owned) do
		local key, amount
		if type(index) == "string" then
			key = index
			amount = type(owned) == "table" and owned.Amount or owned
		elseif type(owned) == "string" then
			key, amount = owned, 1
		elseif type(owned) == "table" then
			key = owned.Key or owned.ItemID or owned.Id or owned.Name or owned.ItemName
			amount = owned.Amount
			if amount == nil then amount = 1 end
		end
		local data = key and WeaponData[key]
		amount = tonumber(amount)
		if type(data) == "table" and (data.ItemType == "Knife" or data.ItemType == "Gun")
			and amount and amount == amount and amount > 0 and amount < math.huge
			and amount == math.floor(amount) then
			local row = byKey[key]
			if not row then
				row = {Key = key, Name = data.ItemName or key, Chroma = data.Chroma == true,
					Amount = 0, Rarity = data.Chroma == true and "Chroma" or data.Rarity or "Common"}
				byKey[key] = row
				table.insert(out, row)
			end
			-- Numeric array entries are individual owned records; dictionary counts
			-- are authoritative if both representations appear in the same payload.
			if type(index) == "string" then row.dictionaryAmount = amount
			else row.Amount = row.Amount + amount end
		end
	end
	for _, row in ipairs(out) do
		row.Amount = row.dictionaryAmount or row.Amount
		row.dictionaryAmount = nil
	end
	return out
end

local PricedRarities = {
	Chroma = true, Godly = true, Ancient = true,
	Vintage = true, Unique = true, Classic = true, Legendary = true,
}

local function FetchPlayerInventory(player)
	if not player or not Runtime.alive then return nil end
	-- Never use ProfileData here: the spawner and local trades intentionally
	-- mutate it, including for LocalPlayer.
	Runtime.serverReads = Runtime.serverReads or setmetatable({}, {__mode = "k"})
	local done, result = false, nil
	local worker = task.spawn(function()
		local thread = coroutine.running()
		Runtime.serverReads[thread] = true
		local ok, raw = pcall(function()
			return game.ReplicatedStorage.Remotes.Extras.GetFullInventory:InvokeServer(player)
		end)
		Runtime.serverReads[thread] = nil
		if ok then result = harvestProfile(raw) end
		done = true
	end)
	local deadline = os.clock() + 10
	while not done and Runtime.alive and os.clock() < deadline do task.wait(0.05) end
	if not done then
		if worker then
			Runtime.serverReads[worker] = nil
			if type(task.cancel) == "function" then pcall(task.cancel, worker) end
		end
		return nil
	end
	return Runtime.alive and result or nil
end

normalizeWeaponName = function(s)
	s = string.lower(tostring(s or ""))

	s = string.gsub(s, "^c%.%s*", "chroma ")
	s = string.gsub(s, "(%s)c%.%s*", "%1chroma ")

	s = string.gsub(s, "['\u{2019}\"]", "")

	s = string.gsub(s, "%s+", " ")
	s = string.gsub(s, "^%s+", "")
	s = string.gsub(s, "%s+$", "")
	return s
end

PlayerCalcPriceTable = {} -- Supreme snapshot is initialized below; no old price fallback.

-- Market estimates use exact weapon identity, not a display-name map that
-- can overwrite a normal weapon with the identically named Chroma variant.
function Runtime.ComputeInventoryUnitValue(itemKey)
	local data = WeaponData[itemKey]
	if type(data) ~= "table" then return nil, "unknown item" end
	local rarity = data.Chroma == true and "Chroma" or data.Rarity
	if rarity == "Classic" then rarity = "Vintage" end
	local names, seen = {}, {}
	local function add(value)
		if type(value) ~= "string" or value == "" then return end
		local name = normalizeWeaponName(value)
		if data.Chroma == true then
			name = name:gsub("chroma$", ""):gsub("^chroma[%s_%-]*", ""):gsub("^%s*(.-)%s*$", "%1")
			name = "chroma " .. name
		end
		if not seen[name] then names[#names+1] = name; seen[name] = true end
	end
	add(data.ItemName); add(data.Name); add(data.DisplayName)
	add(itemKey == "Sorry" and "Corrupt" or itemKey)
	-- Prefer explicit Gun/Knife labels when the site has two same-name skins.
	local typed = {}
	for _, name in ipairs(names) do
		if data.ItemType then typed[#typed+1] = name .. " (" .. string.lower(data.ItemType) .. ")" end
	end
	for _, name in ipairs(names) do typed[#typed+1] = name end
	for _, name in ipairs(typed) do
		local found, value, display, conflict, nonNumeric = false, nil, nil, false, false
		for _, record in ipairs(Values and Values.cache or {}) do
			if record.rarity == rarity and normalizeWeaponName(record.name) == name then
				local current = type(record.value) == "number" and record.value or nil
				if current == nil then nonNumeric = true
				elseif current >= 0 and current < math.huge then
					if found and value ~= current then conflict = true end
					found, value, display = true, current, record.name
				end
			end
		end
		if conflict or nonNumeric then return nil, "ambiguous or non-numeric Supreme value", name end
		if found then
			local source = Values.mode == "live" and "Supreme Values"
				or ("Supreme snapshot " .. tostring(Values.sourceUpdated):sub(1,10))
			return value, source, display
		end
	end
	return nil, "not listed by Supreme", data.ItemName or itemKey
end

function Runtime.InventoryUnitValue(itemKey)
	if not Values or not Values.cache then return Runtime.ComputeInventoryUnitValue(itemKey) end
	local cache = Runtime.unitPriceCache
	if not cache or cache.catalog ~= Values.cache or cache.mode ~= Values.mode or cache.stamp ~= Values.sourceUpdated then
		cache = {catalog=Values.cache,mode=Values.mode,stamp=Values.sourceUpdated,items={}}
		Runtime.unitPriceCache = cache
	end
	local packed = cache.items[itemKey]
	if not packed then
		packed = table.pack(Runtime.ComputeInventoryUnitValue(itemKey))
		cache.items[itemKey] = packed
	end
	return table.unpack(packed,1,packed.n)
end

local function CalculateInventoryValue(inv, playerNameForLog)
	if type(inv) ~= "table" then return nil, {}, {missing = 0, fallback = 0} end
	local total, priced = 0, {}
	local info = {missing = 0, fallback = 0, belowMinimum = 0}
	for _, weapon in ipairs(inv) do
		if PricedRarities[weapon.Rarity] then
			local value, source, name = Runtime.InventoryUnitValue(weapon.Key)
			if value == nil then
				info.missing = info.missing + 1
			elseif value < 50 then
				-- A current low/zero price must not resurrect an older higher price.
				info.belowMinimum = info.belowMinimum + 1
			else
				local contribution = value * weapon.Amount
				total = total + contribution
				if source ~= "Supreme Values" then info.fallback = info.fallback + 1 end
				table.insert(priced, {key = weapon.Key, name = name, amount = weapon.Amount,
					value = value, source = source})
			end
		end
	end
	table.sort(priced, function(a,b) return a.value * a.amount > b.value * b.amount end)
	if playerNameForLog then
		print("[Zoy0m/K1borg] SERVER inventory estimate: " .. playerNameForLog)
		for _, row in ipairs(priced) do
			print(("%s [%s] x%d @ %s = %s (%s)"):format(row.name, row.key, row.amount,
				FormatValue(row.value), FormatValue(row.value * row.amount), row.source))
		end
		print(("TOTAL %s | missing %d | snapshot prices %d | minimum 50"):format(
			FormatValue(total), info.missing, info.fallback))
	end
	Runtime.valueReports = Runtime.valueReports or {}
	if playerNameForLog then
		Runtime.valueReports[playerNameForLog] = {total = total, items = priced, info = info}
	end
	return total, priced, info
end

