local function sortAndReflowPlayers()
	local rows = {}
	for _, r in pairs(playerRows) do table.insert(rows, r) end
	table.sort(rows, function(a, b) return a.total > b.total end)
	for i, r in ipairs(rows) do
		r.container.LayoutOrder = i
		local rank = (r.total > 0) and ("#" .. i .. "  ") or ""
		r.nameLabel.Text = rank .. r.player.Name
	end
end

local function updatePlayerValue(row)
	if not Runtime.alive or not row.container.Parent then return end
	row.requestId = (row.requestId or 0) + 1
	local requestId = row.requestId
	row.valLabel.Text = "fetching…"
	row.valLabel.TextColor3 = Color3.fromRGB(200, 200, 200)

	print(("[mm2run] === Fetching %s's inventory ==="):format(row.player.Name))

	local okFetch, invOrErr = pcall(FetchPlayerInventory, row.player)
	if not Runtime.alive or not row.container.Parent or row.requestId ~= requestId then return end
	if not okFetch then
		warn("[mm2run] FetchPlayerInventory ERRORED for " .. row.player.Name .. ": " .. tostring(invOrErr))
		row.inv = nil
		row.total = -1
		row.priced = {}
		row.valLabel.Text = "err"
		row.valLabel.TextColor3 = Color3.fromRGB(255, 100, 100)
		return
	end
	row.inv = invOrErr

	if not row.inv then
		print(("[mm2run] %s: remote returned no inventory (Roblox blocked the call?)"):format(row.player.Name))
		row.total = -1
		row.priced = {}
		row.valLabel.Text = "N/A"
		row.valLabel.TextColor3 = Color3.fromRGB(200, 150, 100)
		return
	end

	row.valLabel.Text = "pricing…"

	local okCalc, total, priced, info = pcall(CalculateInventoryValue, row.inv, row.player.Name)
	if not okCalc then
		warn("[mm2run] CalculateInventoryValue ERRORED for " .. row.player.Name .. ": " .. tostring(total))
		row.valLabel.Text = "err"
		row.valLabel.TextColor3 = Color3.fromRGB(255, 100, 100)
		row.total = -1
		return
	end

	row.total = total
	row.priced = priced
	row.valLabel.Text = "~" .. FormatValue(total) .. ((info.missing > 0 or info.fallback > 0) and "*" or "")
	row.valLabel:SetAttribute("MissingPrices", info.missing)
	row.valLabel:SetAttribute("SnapshotPrices", info.fallback)
	row.valLabel.TextColor3 = (total > 0) and Color3.fromRGB(96, 194, 255) or Color3.fromRGB(180, 180, 180)
end

function RefreshPlayerValues()
	if Runtime.playersRefreshing then Runtime.playersRefreshPending = true; return end
	if not controlGui.Enabled or currentTab ~= "Players" then Runtime.playersDirty = true; return end
	Runtime.playersRefreshing = true
	task.spawn(function()
		for _, row in pairs(playerRows) do
			if not Runtime.alive or not controlGui.Enabled or currentTab ~= "Players" then break end
			local ok,err = pcall(updatePlayerValue,row)
			if not ok then warn("[Zoy0m/K1borg] Value refresh failed: "..tostring(err)) end
			task.wait(0.1)
		end
		Runtime.playersRefreshing = false
		if Runtime.alive then
			sortAndReflowPlayers()
			playersStatusLabel.Text = "Est. value (50+) · * partial / snapshot"
			if Runtime.playersRefreshPending then
				Runtime.playersRefreshPending = false
				task.defer(RefreshPlayerValues)
			end
		end
	end)
end


playersRefreshBtn.MouseButton1Click:Connect(function()
	RefreshPlayerValues()
end)

local function UpdatePlayers()
	if not Runtime.alive then return end
	Runtime.playersDirty = true
	if not controlGui.Enabled or currentTab ~= "Players" then return end
	Runtime.playersDirty = false
	destroyAllRows()
	for _, player in pairs(game.Players:GetPlayers()) do
		local row = createPlayerRow(player)
		playerRows[player.Name] = row
	end
end

Runtime.OnPlayersTab = function()
	if Runtime.playersDirty ~= false then UpdatePlayers() end
	RefreshPlayerValues()
end
Runtime.Connect(controlGui:GetPropertyChangedSignal("Enabled"),function()
	if controlGui.Enabled and currentTab=="Players" then Runtime.OnPlayersTab() end
end)
Runtime.playersDirty = true
do
	local scheduled = false
	local function schedulePlayers()
		Runtime.playersDirty = true
		if scheduled then return end
		scheduled = true
		task.delay(0.35,function()
			scheduled = false
			if Runtime.alive and controlGui.Enabled and currentTab=="Players" then
				Runtime.OnPlayersTab()
			end
		end)
	end
	Runtime.Connect(game.Players.PlayerAdded,schedulePlayers)
	Runtime.Connect(game.Players.ChildRemoved,function(child)
		if child:IsA("Player") then schedulePlayers() end
	end)
end




