local HttpService = game:GetService("HttpService")

local function urlEncode(s)
	return (tostring(s):gsub("([^%w%-_%.~])", function(c)
		return string.format("%%%02X", string.byte(c))
	end))
end

local httpRequest = (syn and syn.request)
	or (http and http.request)
	or (fluxus and fluxus.request)
	or http_request
	or request

local function withTimeout(fn, timeoutSeconds)
	local done, status, value = false, nil, nil
	task.spawn(function()
		local ok, res = pcall(fn)
		done = true
		if ok then status, value = "ok", res
		else        status, value = "err", res end
	end)
	local t0 = tick()
	while not done and (tick() - t0) < timeoutSeconds do
		task.wait(0.05)
	end
	if not done then return "timeout", nil end
	return status, value
end

-- Supreme Values HTML adapter. Never executes website JavaScript.
Runtime.Supreme = Runtime.Supreme or {}
function Runtime.Supreme.Clean(text)
	text = tostring(text or ""):gsub("<[^>]->", "")
	text = text:gsub("&nbsp;", " "):gsub("&amp;", "&"):gsub("&quot;", '"')
		:gsub("&#39;", "'"):gsub("&apos;", "'"):gsub("&rsquo;", "'")
		:gsub("&lt;", "<"):gsub("&gt;", ">")
	text = text:gsub("&#(%d+);", function(n)
		n = tonumber(n)
		if n and n > 0 and n <= 0x10FFFF then
			local ok, value = pcall(utf8.char, n)
			if ok then return value end
		end
		return ""
	end)
	return (text:gsub("%s+", " "):gsub("^%s*(.-)%s*$", "%1"))
end
function Runtime.Supreme.Number(text)
	text = Runtime.Supreme.Clean(text):gsub(",", "")
	if not text:match("^%d+%.?%d*$") then return nil end
	local value = tonumber(text)
	return value and value >= 0 and value < math.huge and value or nil
end
function Runtime.Supreme.Parse(html, category)
	if type(html) ~= "string" or #html < 1000 or #html > 6000000 then
		return nil, "Blocked or empty page"
	end
	-- Exclude hidden popup data and script dictionaries, which contain decoy prices.
	local clean = html:gsub("<script[^>]*>.-</script>", ""):gsub("<!--.-%-%->", "")
	local stamp = clean:match('data%-updated%-iso=["\']([^"\']+)')
	if not stamp then return nil, "Source date missing" end
	local blocks, cursor = {}, 1
	while true do
		local first, last, attrs = clean:find('<div([^>]-class=["\']itemcolumn["\'][^>]*)>', cursor)
		if not first then break end
		table.insert(blocks, {first = first, last = last, attrs = attrs})
		cursor = last + 1
	end
	local out, seen = {}, {}
	for index, block in ipairs(blocks) do
		local style = (block.attrs:match('style=["\']([^"\']*)') or ""):lower():gsub("%s", "")
		if not style:find("display:none", 1, true) and not style:find("visibility:hidden", 1, true)
			and not block.attrs:match("%shidden[%s=>]") then
			local body = clean:sub(block.last + 1, blocks[index + 1] and blocks[index + 1].first - 1 or #clean)
			local name = body:match('<div[^>]-class=["\']itemhead["\'][^>]*>(.-)</div>')
			local valueText = body:match('<b[^>]-class=["\']itemvalue[^"\']*["\'][^>]*>(.-)</b>')
			local id = body:match('<div[^>]-class=["\']itemcell["\'][^>]-id=["\']([^"\']+)')
			if name and valueText and id then
				name, valueText = Runtime.Supreme.Clean(name), Runtime.Supreme.Clean(valueText)
				if name ~= "" and valueText ~= "" and not seen[id] then
					seen[id] = true
					if category == "Chroma" then name = name:gsub("^[Cc]%.%s*", "Chroma ") end
					local numeric = Runtime.Supreme.Number(valueText)
					local range = Runtime.Supreme.Clean(body:match('<b[^>]-class=["\']itemrange[^"\']*["\'][^>]*>(.-)</b>'))
					local trend = Runtime.Supreme.Clean(body:match('<b[^>]-class=["\']itemstability[^"\']*["\'][^>]*>(.-)</b>'))
					local demand = Runtime.Supreme.Clean(body:match("Demand%s*%-%s*<b[^>]*>(.-)</b>"))
					table.insert(out, {id = id, name = name, value = numeric or valueText,
						_numericValue = numeric, rarity = category, range = range,
						trend = trend, demand = demand,
						year = block.attrs:match('data%-year=["\']([^"\']*)') or "",
						source = "Supreme Values", updatedIso = stamp})
				end
			end
		end
	end
	if #out == 0 then return nil, "No visible item cards" end
	return out, stamp
end

local function FetchAllValues(onProgress)
	local pages = {
		{"uniques", "Unique"}, {"ancients", "Ancient"}, {"vintages", "Vintage"},
		{"chromas", "Chroma"}, {"godlies", "Godly"}, {"legendaries", "Legendary"},
		{"rares", "Rare"}, {"uncommons", "Uncommon"}, {"commons", "Common"},
	}
	local all, stamp = {}, nil
	for index, page in ipairs(pages) do
		if not Runtime.alive then return nil, false, "Cancelled" end
		local url = "https://supremevalues.com/mm2/" .. page[1]
		local body
		if type(httpRequest) == "function" then
			local status, response = withTimeout(function()
				return httpRequest({Url = url, Method = "GET",
					Headers = {["Accept"] = "text/html", ["Cache-Control"] = "no-cache"}})
			end, 12)
			if status == "ok" and type(response) == "table" then
				local code = tonumber(response.StatusCode or response.Status)
				if code and code >= 200 and code < 300 then body = response.Body or response.body end
			end
		else
			local status, response = withTimeout(function() return game:HttpGet(url) end, 12)
			if status == "ok" then body = response end
		end
		local rows, sourceDate = Runtime.Supreme.Parse(body, page[2])
		if not rows then return nil, false, page[1] .. ": " .. tostring(sourceDate) end
		if stamp and stamp ~= sourceDate then return nil, false, "Site update in progress; retry later" end
		stamp = sourceDate
		for _, row in ipairs(rows) do
			row.url = url .. "?item=" .. urlEncode(row.id)
			table.insert(all, row)
		end
		if onProgress then onProgress(index, #pages) end
	end
	-- Publish only a complete, same-revision catalog. A failed page cannot erase good data.
	return all, true, stamp
end


RebuildValuesIndex = function()
	Values.byName, Values.byNormalizedName = {}, {}
	local conflicts = {}
	for _, item in ipairs(Values.cache or {}) do
		local name = normalizeWeaponName(item.name)
		local key = name .. "|" .. tostring(item.rarity)
		if not conflicts[key] then
			local old = Values.byNormalizedName[key]
			if old and old.value ~= item.value then
				Values.byNormalizedName[key] = nil
				conflicts[key] = true
			else Values.byNormalizedName[key] = item end
		end
	end
	if type(ScheduleRandomGodlyPoolRebuild) == "function" then
		ScheduleRandomGodlyPoolRebuild("Supreme Values catalog")
	end
end
RebuildValuesIndex()

