		valLbl.Font = Enum.Font.GothamMedium
		valLbl.TextSize = type(item.value) == "number" and 14 or 10
		valLbl.TextColor3 = Color3.fromRGB(96, 194, 255)
		valLbl.TextXAlignment = Enum.TextXAlignment.Right
		valLbl.Parent = row
	end
end

local function FilterCachedValues(query)
	if not Values.cache then return nil end
	if query == nil or query == "" then return Values.cache end
	local q = string.lower(query)
	local out = {}
	for _, item in ipairs(Values.cache) do
		local name = string.lower(tostring(item.name or ""))
		local rarity = string.lower(tostring(item.rarity or ""))
		if string.find(name .. " " .. tostring(item.year or ""), q, 1, true) or string.find(rarity, q, 1, true) then
			table.insert(out, item)
		end
	end
	return out
end

local function RenderFilteredResults(query)
	local items = FilterCachedValues(query)
	if not items then
		RenderValueResults({})
		return 0, 0
	end
	local total = #items
	local capped = items
	if total > 250 then
		capped = {}
		for i = 1, 250 do capped[i] = items[i] end
	end
	RenderValueResults(capped)
	return #capped, total
end

local function UpdateValuesStatus(query)
	if not Runtime.alive or not Values.cache then return end
	local shown, total = RenderFilteredResults(query)
	local date = tostring(Values.sourceUpdated or "?"):sub(1,10)
	local mode = Values.mode == "live" and "Live" or "Snapshot"
	if Values.lastError then mode = mode .. " · refresh failed" end
	local checked = Values.checkedAt and ("Checked " .. Values.checkedAt .. " UTC") or "Checked 2026-09-09 · bundled"
	valueStatusLabel.Text = ("Supreme · %s · %s\n%s\n%d/%d matches"):format(mode, date, checked, shown, total)
	valueStatusLabel.TextColor3 = Values.lastError and Color3.fromRGB(255, 196, 105) or Color3.fromRGB(115, 225, 255)
end

local function LoadFullCatalog(force)
	if not Runtime.alive or Values.fetching then return end
	if not force and Values.mode == "live" and tick() - Values.fetchedAt < 600 then
		UpdateValuesStatus(valueSearchBox.Text)
		return
	end
	Values.fetching = true
	task.spawn(function()
		local callOk, items, complete, detail = pcall(FetchAllValues, function(page, count)
			if Runtime.alive then valueStatusLabel.Text = ("Supreme · loading %d/%d\nSaved prices remain available"):format(page, count) end
		end)
		Values.fetching = false
		if not Runtime.alive then return end
		if callOk and complete and items and #items > 0 then
			Values.cache = items
			Values.sourceUpdated = detail
			Values.mode = "live"
			Values.lastError = nil
			Values.fetchedAt = tick()
			Values.checkedAt = os.date("!%Y-%m-%d %H:%M")
			RebuildValuesIndex()
			RefreshPlayerValues()
		else
			Values.lastError = tostring(callOk and detail or items)
			Values.mode = "snapshot"
			warn("[Zoy0m/K1borg] Supreme refresh failed; retaining dated snapshot: " .. Values.lastError)
		end
		UpdateValuesStatus(valueSearchBox.Text)
	end)
end
UpdateValuesStatus("")


