-- BEGIN MM2 MENU INPUT
-- P remains the keyboard toggle.  On iPad/mobile, double-tap with ONE finger
-- in the game's top-right corner, just below the Roblox top bar.  These UIS
-- connections are independent of ScreenGui.Enabled, so the hidden menu can
-- always be reopened without adding an on-screen button or blocking touches.
do
	local GuiService = game:GetService("GuiService")
	local controller = {Gui = controlGui, connections = {}, destroyed = false}
	local config = {
		maxTapDuration = 0.25,
		doubleTapInterval = 0.42,
		maxMovement = 20,
		maxTapDistance = 44,
		repeatDelay = 0.40,
		minZoneSize = 96,
		maxZoneSize = 140,
	}
	local activeTouches, activeCount = {}, 0
	local candidate, lastTap = nil, nil
	local cooldownUntil = 0

	local function connect(signal, callback)
		local connection = signal:Connect(callback)
		table.insert(controller.connections, connection)
		return connection
	end

	local function resetTouches()
		activeTouches, activeCount = {}, 0
		candidate, lastTap = nil, nil
		cooldownUntil = 0
	end

	function controller.Destroy()
		if controller.destroyed then return end
		controller.destroyed = true
		Runtime.Destroy()
		for _, connection in ipairs(controller.connections) do
			pcall(function() connection:Disconnect() end)
		end
		controller.connections = {}
		resetTouches()
		if rawget(_G, "MM2MenuInputController") == controller then
			_G.MM2MenuInputController = nil
		end
	end

	local function toggleMenu(reason)
		if controller.destroyed or not controlGui.Parent then return false end
		-- Read the real state, rather than keeping a second, stale visibility flag.
		local visible = not controlGui.Enabled
		controlGui.Enabled = visible
		if not visible then Drag.mode, Drag.corner = nil, nil end
		print("[mm2run] GUI " .. (visible and "shown" or "hidden") .. " (" .. tostring(reason) .. ")")
		return true
	end

	local function canGesture()
		if controller.destroyed or not controlGui.Parent then return false end
		if UserInputService:GetFocusedTextBox() then return false end
		local robloxMenuOpen = false
		pcall(function() robloxMenuOpen = GuiService.MenuIsOpen == true end)
		return not robloxMenuOpen
	end

	local function cornerAt(position)
		local camera = workspace.CurrentCamera
		if not camera then return nil end
		local viewport = camera.ViewportSize
		if viewport.X <= 0 or viewport.Y <= 0 then return nil end
		local insetTop, insetRight = 0, 0
		pcall(function()
			local topLeft, bottomRight = GuiService:GetGuiInset()
			insetTop = math.max(0, topLeft.Y)
			insetRight = math.max(0, bottomRight.X)
		end)
		local size = math.max(config.minZoneSize,
			math.min(config.maxZoneSize, math.min(viewport.X, viewport.Y) * 0.14))
		-- Keep the target INSIDE the game, not on the iPadOS Control Center edge.
		local right = viewport.X - insetRight - 12
		local top = math.max(12, insetTop + 8)
		local bottom = math.min(viewport.Y - 12, top + size)
		if position.X < right - size or position.X > right
			or position.Y < top or position.Y > bottom then return nil end
		return viewport
	end

	local function distanceSquared(a, b)
		local dx, dy = a.X - b.X, a.Y - b.Y
		return dx * dx + dy * dy
	end

	connect(UserInputService.TouchStarted, function(input)
		if controller.destroyed or activeTouches[input] then return end
		activeTouches[input] = true
		activeCount = activeCount + 1
		if activeCount ~= 1 or not canGesture() or os.clock() < cooldownUntil then
			candidate, lastTap = nil, nil
			return
		end
		local viewport = cornerAt(input.Position)
		if not viewport then candidate, lastTap = nil, nil return end
		candidate = {
			input = input,
			position = Vector2.new(input.Position.X, input.Position.Y),
			startedAt = os.clock(),
			viewportX = viewport.X,
			viewportY = viewport.Y,
			moved = false,
		}
	end)

	connect(UserInputService.TouchMoved, function(input)
		if candidate and candidate.input == input
			and distanceSquared(input.Position, candidate.position) > config.maxMovement * config.maxMovement then
			candidate.moved = true
		end
	end)

	connect(UserInputService.TouchEnded, function(input)
		if not activeTouches[input] then return end
		activeTouches[input] = nil
		activeCount = math.max(0, activeCount - 1)
		local tap = candidate
		if not tap or tap.input ~= input then return end
		candidate = nil
		local now = os.clock()
		local viewport = cornerAt(input.Position)
		if not canGesture() or activeCount ~= 0 or not viewport or tap.moved
			or input.UserInputState == Enum.UserInputState.Cancel
			or now - tap.startedAt > config.maxTapDuration
			or distanceSquared(input.Position, tap.position) > config.maxMovement * config.maxMovement
			or viewport.X ~= tap.viewportX or viewport.Y ~= tap.viewportY then
			lastTap = nil
			return
		end
		if lastTap and now - lastTap.time <= config.doubleTapInterval
			and viewport.X == lastTap.viewportX and viewport.Y == lastTap.viewportY
			and distanceSquared(input.Position, lastTap.position) <= config.maxTapDistance * config.maxTapDistance then
			lastTap = nil
			cooldownUntil = now + config.repeatDelay
			toggleMenu("top-right double-tap")
		else
			lastTap = {
				time = now,
				position = Vector2.new(input.Position.X, input.Position.Y),
				viewportX = viewport.X,
				viewportY = viewport.Y,
			}
		end
	end)

	-- Prevent stale taps after opening Control Center, backgrounding Roblox,
	-- destroying the GUI or re-running this script.  No per-frame polling.
	connect(UserInputService.WindowFocusReleased, resetTouches)
	pcall(function() connect(controlGui.Destroying, controller.Destroy) end)

	connect(UserInputService.InputBegan, function(input, gameProcessed)
		if controller.destroyed or gameProcessed or UserInputService:GetFocusedTextBox() then return end
		local key = input.KeyCode

		if key == Enum.KeyCode.P then
			resetTouches()
			toggleMenu("P")

		elseif key == Enum.KeyCode.M then
			local ok, err = pcall(StartTrade)
			print(ok and "[mm2run] trade started (M)" or ("[mm2run] start trade failed: " .. tostring(err)))

		elseif key == Enum.KeyCode.N then
			local ok, err = pcall(function() AddRandomPricedWeapon("regular") end)
			if not ok then warn("[mm2run/random] N failed: " .. tostring(err)) end

		elseif key == Enum.KeyCode.C then
			local ok, err = pcall(function() AddRandomPricedWeapon("small") end)
			if not ok then warn("[mm2run/random] C failed: " .. tostring(err)) end

		elseif key == Enum.KeyCode.B then
			local ok, accepted = pcall(AcceptTheirOfferAction)
			if ok and accepted then print("[mm2run] offer accepted (B)") end

		elseif key == Enum.KeyCode.V then
			local ok, err = pcall(function()
				local selected = Players:FindFirstChild(tostring(TradeTable.Player2.Player or ""))
				if selected then
					SilentBlockPlayer(selected)
					print("[mm2run] block player (V): " .. selected.Name)
				else
					print("[mm2run] no online selected player to block")
				end
			end)
			if not ok then warn("[mm2run] V failed: " .. tostring(err)) end

		elseif key == Enum.KeyCode.Z then
			local ok, err = pcall(UseRecentTradePartner)
			if not ok then warn("[mm2run/recent] Z failed: " .. tostring(err)) end

		elseif key == Enum.KeyCode.Q then
			local ok, err = pcall(TriggerWearFakeWeapon)
			if not ok then warn("[mm2run/fake-wear] Q failed: " .. tostring(err)) end
		end
	end)

	_G.MM2MenuInputController = controller
	print("[mm2run] Hotkeys: P=GUI | M=Trade | N=Random 50-20k | C=Small 50-500 | B=Accept | V=Block | Z=Recent | Q=Wear")
	print("[mm2run] iPad/mobile: double-tap the TOP-RIGHT game corner below the top bar to hide/show the menu")
end
-- END MM2 MENU INPUT

